/* Receivables dashboard same-size modern layout */
body[data-view="overview"]{background:#f2f7fc;color:#071f3f;}
body[data-view="overview"] .topbar{height:60px;background:rgba(255,255,255,.94);box-shadow:0 1px 0 rgba(15,38,72,.08);padding:0 28px;}
body[data-view="overview"] .breadcrumb{display:flex;align-items:center;gap:8px;font-size:12px;color:#6980a0;}
body[data-view="overview"] .breadcrumb strong{font-size:18px!important;color:#061c3b!important;font-weight:850;letter-spacing:-.35px;}
body[data-view="overview"] .breadcrumb span{margin:0!important;color:#8090a6;}
body[data-view="overview"] .snapshot-badge{border:1px solid #dbe7f3;background:#f8fbff;border-radius:13px;padding:8px 14px;font-size:12px;color:#173862;}
body[data-view="overview"] .snapshot-badge:before{width:8px;height:8px;background:#14bd72;}
body[data-view="overview"] .icon-button{width:36px;height:36px;border:1px solid transparent;border-radius:12px;color:#0d2b55;background:#fff;}
body[data-view="overview"] .icon-button:hover{border-color:#dce8f4;background:#f7fbff;}
body[data-view="overview"] .server-user{font-size:12px;border-left:0;color:#0a294f;padding-left:4px;}
body[data-view="overview"] .server-user strong{color:#071f3f;font-weight:850;}
body[data-view="overview"] .server-link{font-size:12px;color:#0a294f;font-weight:700;text-decoration:none;}
body[data-view="overview"] .content{max-width:1420px;padding:18px 28px 22px;margin:0 auto;}
body[data-view="overview"] .heading-row{display:none;}
body[data-view="overview"] .mobile-nav{display:none;}
body[data-view="overview"] .source-bar{background:#fff;border:1px solid #dfeaf5;border-radius:13px;box-shadow:0 6px 18px rgba(12,40,76,.06);padding:14px 16px;margin-bottom:18px;display:flex;align-items:center;gap:14px;}
body[data-view="overview"] .source-file{background:#eafbf2;color:#0b8c56;border-radius:10px;padding:9px 12px;font-size:12px;font-weight:850;white-space:nowrap;}
body[data-view="overview"] .source-file svg{display:none;}
body[data-view="overview"] .source-file span{max-width:none;}
body[data-view="overview"] .source-file span:before{content:"Google Sheet live";}
body[data-view="overview"] .source-file span{font-size:0;}
body[data-view="overview"] .source-file span:before{font-size:12px;}
body[data-view="overview"] .source-file:before{content:"";width:9px;height:9px;border-radius:999px;background:#17c878;box-shadow:0 0 0 5px rgba(23,200,120,.11);}
body[data-view="overview"] .source-controls{flex:1;justify-content:flex-end;gap:10px;}
body[data-view="overview"] .source-controls label,body[data-view="overview"] .top-range-label{font-size:12px;color:#385675;letter-spacing:0;text-transform:none;font-weight:650;padding:0;}
body[data-view="overview"] .source-controls input,body[data-view="overview"] .source-controls select{height:40px;border-radius:8px;border-color:#d7e4f1;font-size:13px;color:#082345;background:#fff;padding:7px 10px;}
body[data-view="overview"] .source-controls #unit{display:none;}
body[data-view="overview"] .source-controls .live-pill{display:none;}
body[data-view="overview"] .live-pill{height:38px;border-radius:10px;padding:8px 12px;font-size:12px;font-weight:850;background:#eafbf2;color:#0b8c56;border-color:#d6f2e4;}
body[data-view="overview"] .sync-google{height:42px;border-radius:10px;background:#0d78f2!important;color:#fff!important;border-color:#0d78f2!important;font-size:13px;font-weight:850;padding:0 18px;box-shadow:0 8px 18px rgba(13,120,242,.22);}
body[data-view="overview"] #filterCard,body[data-view="overview"] #selectionLine,body[data-view="overview"] #dateRangeNotice{display:none!important;}
body[data-view="overview"] #kpiGrid{display:block!important;margin-bottom:14px;}
.rms-main-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:0 0 16px;}
.rms-big-kpi{position:relative;overflow:hidden;min-height:122px;border-radius:12px;border:0;color:#fff;box-shadow:0 10px 24px rgba(15,48,92,.12);padding:22px 24px 46px;cursor:pointer;text-align:left;}
.rms-big-kpi:after{content:"";position:absolute;inset:auto 0 0;height:34px;background:rgba(0,0,0,.16);}
.rms-big-kpi .rms-kpi-main{font-size:29px;line-height:1;font-weight:900;letter-spacing:-.7px;margin-bottom:9px;position:relative;z-index:2;}
.rms-big-kpi .rms-kpi-label{font-size:13px;font-weight:650;position:relative;z-index:2;}
.rms-big-kpi .rms-kpi-icon{position:absolute;right:18px;top:20px;width:70px;height:70px;border-radius:18px;display:grid;place-items:center;opacity:.16;color:#001d44;}
.rms-big-kpi .rms-kpi-icon svg{width:64px;height:64px;stroke-width:1.5;}
.rms-big-kpi .rms-more{position:absolute;left:0;right:0;bottom:9px;z-index:2;text-align:center;font-weight:850;font-size:12px;color:rgba(255,255,255,.95);}
.rms-big-kpi.blue{background:linear-gradient(135deg,#07327c 0%,#0055d9 100%);}
.rms-big-kpi.green{background:linear-gradient(135deg,#07955f 0%,#05ac72 100%);}
.rms-big-kpi.sky{background:linear-gradient(135deg,#1175f6 0%,#0097ff 100%);}
.rms-big-kpi.yellow{background:linear-gradient(135deg,#ffcb1f 0%,#f5a900 100%);color:#082345;}
.rms-big-kpi.yellow:after{background:rgba(151,104,0,.22);}
.rms-big-kpi.yellow .rms-more{color:#082345;}
.rms-mini-kpis{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));background:#fff;border:1px solid #dfe9f4;border-radius:12px;box-shadow:0 8px 20px rgba(15,48,92,.06);overflow:hidden;margin-bottom:16px;}
.rms-mini-kpi{display:flex;align-items:center;gap:14px;padding:18px 18px;min-height:84px;border-right:1px solid #e4edf6;background:#fff;cursor:pointer;text-align:left;}
.rms-mini-kpi:last-child{border-right:0;}
.rms-mini-kpi:hover{background:#f8fbff;}
.rms-mini-kpi .mini-icon{width:42px;height:42px;border-radius:10px;display:grid;place-items:center;color:#fff;flex:0 0 auto;}
.rms-mini-kpi .mini-icon svg{width:23px;height:23px;}
.rms-mini-kpi strong{display:block;font-size:22px;line-height:1;font-weight:900;color:#071f3f;margin-bottom:4px;}
.rms-mini-kpi span{display:block;color:#365577;font-size:11px;line-height:1.2;}
.rms-mini-kpi .mini-icon.blue{background:#1175f6}.rms-mini-kpi .mini-icon.red{background:#fb2b38}.rms-mini-kpi .mini-icon.green{background:#11a968}.rms-mini-kpi .mini-icon.purple{background:#8d36f4}.rms-mini-kpi .mini-icon.orange{background:#fb7f09}.rms-mini-kpi .mini-icon.slate{background:#49677f}.rms-mini-kpi .mini-icon.teal{background:#00bcb8}
.rms-chart-row{display:grid;grid-template-columns:1.45fr 1.05fr 1.15fr;gap:14px;margin-bottom:14px;}
.rms-bottom-row{display:grid;grid-template-columns:1.05fr 1fr;gap:14px;margin-bottom:14px;}
.rms-panel{background:#fff;border:1px solid #dfe9f4;border-radius:12px;box-shadow:0 8px 20px rgba(15,48,92,.07);min-width:0;overflow:hidden;}
