.rms-table th{background:#f2f6fb;color:#0a2448;font-size:11px;text-transform:none;letter-spacing:0;font-weight:900;padding:9px 11px;border-top:1px solid #e0e9f3;border-bottom:1px solid #e0e9f3;white-space:nowrap;}
.rms-table th:first-child{border-left:1px solid #e0e9f3;border-radius:8px 0 0 0}.rms-table th:last-child{border-right:1px solid #e0e9f3;border-radius:0 8px 0 0}.rms-table td{padding:9px 11px;border-bottom:1px solid #e8eef5;white-space:nowrap;}.rms-table tbody tr:hover{background:#f8fbff}.rms-table .num{text-align:right;font-variant-numeric:tabular-nums}.rms-table .red{color:#ef2635;font-weight:900}.rms-table .green{color:#0f9e62;font-weight:850}.rms-table .orange{color:#f16a00;font-weight:850}.rms-table .blue{color:#006ee8;font-weight:850}.rms-empty{padding:35px 16px;text-align:center;color:#6d829a;font-size:12px;}
