@media(max-width:1180px){.rms-main-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.rms-mini-kpis{grid-template-columns:repeat(3,minmax(0,1fr))}.rms-chart-row,.rms-bottom-row{grid-template-columns:1fr}.rms-ageing-wrap{grid-template-columns:1fr;justify-items:center}body[data-view="overview"] .source-bar{align-items:flex-start;flex-direction:column}body[data-view="overview"] .source-controls{justify-content:flex-start;width:100%;}}
@media(max-width:720px){body[data-view="overview"] .content{padding:14px 12px}.rms-main-kpis{grid-template-columns:1fr}.rms-mini-kpis{grid-template-columns:1fr}.rms-mini-kpi{border-right:0;border-bottom:1px solid #e4edf6}.rms-big-kpi{min-height:106px}.rms-chart-host{height:210px}body[data-view="overview"] .source-controls{display:grid;grid-template-columns:1fr 1fr}body[data-view="overview"] .source-controls label,body[data-view="overview"] .top-range-label{grid-column:1 / -1}.topbar{padding:0 12px!important}}

