<style>
/* Modern Tailwind-inspired visual layer. Existing CSS remains as offline fallback. */
:root{--brand-blue:#2477f3;--brand-blue-2:#1c64df;--nav:#0d2748;--nav2:#102f55;--bg:#f3f7fc;--panel:#fff;--ink:#10223f;--muted:#6e819a;--line:#dce7f3;--shadow:0 12px 35px rgba(28,67,108,.08)}
body{background:linear-gradient(135deg,#f6f9fd 0%,#eef5fc 56%,#f8fbff 100%);color:var(--ink)}
.sidebar{width:232px;background:linear-gradient(180deg,#102c50 0%,#0b2340 62%,#091d35 100%);padding:24px 14px 18px;box-shadow:8px 0 30px rgba(11,37,67,.08)}
main{margin-left:232px}.brand{margin:0 10px 30px;gap:10px}.brand-mark{display:none}.brand strong{font-size:26px;letter-spacing:1.3px;font-weight:850}.brand small{display:block;margin-top:1px;letter-spacing:3px;color:#9db4cf;font-size:7px}.workspace-label{margin:0 13px 10px;color:#6f8dac;font-size:8px}
.nav-item{border-radius:10px;margin:3px 0;padding:11px 12px;font-size:12px;color:#c5d4e5;transition:.18s ease}.nav-item:hover{background:rgba(74,132,194,.18);transform:translateX(2px)}.nav-item.active{background:linear-gradient(135deg,#2380ff,#1d68dd);color:#fff;box-shadow:0 8px 20px rgba(36,119,243,.25);inset:auto}.nav-item.active .icon{stroke-width:2}.nav-count{background:rgba(255,255,255,.14);color:#eaf3ff}.sidebar-bottom .offline-card{background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.08);border-radius:12px}
.topbar{height:68px;position:sticky;top:0;z-index:15;background:rgba(255,255,255,.92);backdrop-filter:blur(12px);border-bottom:1px solid #e4edf6;padding:0 28px;box-shadow:0 3px 18px rgba(37,72,110,.035)}.breadcrumb{font-size:12px;color:#536d88;font-weight:650}.topbar-right{gap:10px}.snapshot-badge{background:#f1f7fd;border:1px solid #dceaf7;border-radius:999px;padding:6px 10px;color:#53708c;font-weight:600}
.content{max-width:1720px;padding:24px 28px 0}.heading-row{margin-bottom:16px}.eyebrow{color:#2477f3}.heading-row h1{font-size:27px;color:#0f2340}.page-subtitle{font-size:12px;color:#6c819a}.header-actions{gap:9px}.btn{height:38px;border-radius:9px;border-color:#d5e2ef;font-size:10px;box-shadow:0 2px 6px rgba(33,70,108,.025)}.btn:hover{background:#f5f9fd;border-color:#bcd1e5}.btn.primary{background:linear-gradient(135deg,#2477f3,#1765dc);border-color:#2477f3;box-shadow:0 7px 18px rgba(36,119,243,.2)}
.source-bar{background:#fff;border:1px solid #dfe9f3;border-radius:14px;padding:10px 12px;box-shadow:var(--shadow);margin-bottom:12px}.source-file{padding-left:4px}.source-controls{gap:7px}.source-controls input,.source-controls select{border-radius:8px;border-color:#d9e5f0;background:#fbfdff}.top-range-label{color:#2477f3}
.filter-card{border-radius:14px;border-color:#dde8f3;box-shadow:var(--shadow);padding:14px 16px}.field label{color:#5b728b;font-weight:700}.field input,.field select{border-radius:9px;border-color:#d8e4ef;background:#fbfdff}.input-icon input{background:#fbfdff}.more-filters{border-radius:9px}
.selection-line{padding:11px 2px 9px}.kpi-grid{gap:12px}.kpi{border-radius:14px;border-color:#dfe9f2;box-shadow:var(--shadow);padding:17px 18px}.kpi.featured{border-top:0;background:linear-gradient(135deg,#eef6ff,#fff)}.kpi-value{font-size:27px}.kpi-symbol{border-radius:10px}.panel{border-radius:15px;border-color:#dde8f2;box-shadow:var(--shadow)}.panel-heading{padding:17px 18px 10px}.panel-heading h2{font-size:14px;color:#17304f}.panel-heading p{color:#8292a5}.panel-tag{border-radius:999px;padding:5px 8px;background:#eef4fa;color:#617993}
.ledger th{background:#f5f8fc;color:#667f99;padding:12px 12px}.ledger td{padding:11px 12px;color:#536b84}.ledger tbody tr:hover{background:#f5faff}.ledger tfoot td{background:#edf5ff;color:#244e78;border-top-color:#d5e6f6}
.server-user{background:#f6f9fd;border:1px solid #dce7f2!important;border-radius:999px;padding:5px 9px!important;gap:5px!important}.server-user strong{display:inline-flex;align-items:center;gap:6px}.server-user strong:before{content:'A';display:inline-grid;place-items:center;width:26px;height:26px;border-radius:50%;background:linear-gradient(135deg,#4666ed,#2b80f4);color:#fff;font-weight:800;font-size:11px}.server-link{font-weight:650}
.live-pill{border-radius:10px!important;padding:7px 10px!important}.sync-google{background:linear-gradient(135deg,#12ad61,#07964e)!important;border-color:#0ca457!important;color:#fff!important;border-radius:9px!important;box-shadow:0 7px 18px rgba(12,164,87,.18)}
