.procure-note strong{display:block;color:#173b62;font-size:13px;margin-bottom:3px}.procure-note small{display:block;color:#6b8199;line-height:1.55}.procure-note .procure-pill{border:1px solid #b9d5f2;background:#fff;color:#22619e;border-radius:999px;padding:5px 9px;font-size:9px;font-weight:850;white-space:nowrap}
.procure-filter-bar{display:grid;grid-template-columns:minmax(220px,1.4fr) minmax(170px,.8fr) minmax(170px,.8fr) auto;gap:10px;align-items:end;background:#fff;border:1px solid var(--line);border-radius:12px;padding:14px 15px;margin-bottom:14px;box-shadow:var(--shadow)}
.procure-filter-bar label{display:block;font-size:9px;font-weight:800;color:#6f8095;margin-bottom:5px;text-transform:uppercase;letter-spacing:.4px}.procure-filter-bar input,.procure-filter-bar select{height:34px;font-size:11px;width:100%;border-radius:8px}.procure-filter-bar .btn{height:34px;font-size:10px;padding:7px 10px}
.procure-kpi-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:14px}.procure-kpi{position:relative;overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:13px;padding:15px 16px;box-shadow:var(--shadow)}.procure-kpi:after{content:'';position:absolute;right:-22px;top:-30px;width:76px;height:76px;border-radius:50%;background:#eef7ff}.procure-kpi.warn:after{background:#fff4df}.procure-kpi.good:after{background:#eaf8f3}.procure-kpi.danger:after{background:#fff0ef}.procure-kpi span{position:relative;z-index:1;display:block;font-size:9px;letter-spacing:.65px;color:#7b8b9c;font-weight:850;text-transform:uppercase}.procure-kpi strong{position:relative;z-index:1;display:block;margin-top:6px;font-size:25px;letter-spacing:-.6px;color:#17304d}.procure-kpi small{position:relative;z-index:1;color:#8796a7;font-size:10px;line-height:1.4}.procure-kpi.good strong{color:#168367}.procure-kpi.warn strong{color:#b87916}.procure-kpi.danger strong{color:#b35450}
.procure-overview-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0 0 16px}.procure-overview-card{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;gap:14px;background:#fff;border:1px solid var(--line);border-radius:13px;padding:15px 17px;min-height:96px;box-shadow:var(--shadow);text-align:left;width:100%;font:inherit}.procure-overview-card.clickable{cursor:pointer;transition:transform .16s ease,border-color .16s ease,box-shadow .16s ease;background:linear-gradient(135deg,#fff,#f8fbff)}.procure-overview-card.clickable:hover{transform:translateY(-1px);border-color:#74b7ff;box-shadow:0 12px 28px rgba(12,74,139,.13)}.procure-overview-card.active{border-color:#1182ff;box-shadow:0 0 0 2px rgba(17,130,255,.17),0 12px 28px rgba(12,74,139,.16)}.procure-overview-card.active:after{content:'Data shown below';position:absolute;right:12px;bottom:8px;font-size:9px;font-weight:900;color:#0b74de;background:#e9f4ff;border:1px solid #b9ddff;border-radius:999px;padding:3px 8px}.procure-overview-card:before{content:'';position:absolute;inset:auto 0 0 0;height:3px;background:#d9ecff}.procure-overview-card .procure-overview-copy{position:relative;z-index:1;min-width:0}.procure-overview-card span{display:block;font-size:9px;letter-spacing:.7px;color:#355a7e;font-weight:900;text-transform:uppercase}.procure-overview-card strong{display:block;margin-top:7px;font-size:27px;line-height:1;color:#06365d;letter-spacing:-.7px}.procure-overview-card small{display:block;margin-top:8px;font-size:10px;line-height:1.35;color:#4e6f8e}.procure-overview-icon{position:relative;z-index:1;display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;width:48px;height:48px;border-radius:18px;background:#edf6ff;color:#0d78db}.procure-overview-icon .icon{width:25px;height:25px;stroke-width:2.2}.procure-overview-card.good:before{background:#bdebdc}.procure-overview-card.good .procure-overview-icon{background:#e9fbf4;color:#008a7b}.procure-overview-card.good strong{color:#008a7b}.procure-overview-card.warn:before{background:#ffd9a3}.procure-overview-card.warn .procure-overview-icon{background:#fff3e3;color:#c25b00}.procure-overview-card.warn strong{color:#c25b00}.procure-overview-card.danger:before{background:#ffc6cf}.procure-overview-card.danger .procure-overview-icon{background:#fff0f3;color:#c50018}.procure-overview-card.danger strong{color:#c50018}.procure-overview-card.info:before{background:#cfe7ff}.procure-overview-card.info .procure-overview-icon{background:#edf6ff;color:#0d78db}.procure-overview-card.info strong{color:#06365d}

.procure-grid{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:14px;margin-bottom:14px}.procure-mini-chart{padding:4px 18px 18px}.procure-bar{display:grid;grid-template-columns:minmax(90px,170px) 1fr minmax(80px,auto);gap:10px;align-items:center;margin:10px 0;font-size:10px;color:#5d7186}.procure-bar-label{font-weight:750;color:#344b63;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.procure-bar-track{height:9px;background:#eef3f8;border-radius:999px;overflow:hidden}.procure-bar-fill{height:100%;background:#2788cf;border-radius:999px}.procure-bar-fill.warn{background:#de9b35}.procure-bar-fill.good{background:#2aa17d}.procure-bar-fill.danger{background:#c96058}.procure-bar-value{text-align:right;font-weight:850;color:#17304d}.procure-summary-box{padding:16px 18px;display:grid;gap:10px}.procure-summary-row{display:grid;grid-template-columns:1fr minmax(88px,auto);gap:10px;font-size:11px;border-bottom:1px solid #eef2f6;padding-bottom:8px}.procure-summary-row:last-child{border-bottom:0;padding-bottom:0}.procure-summary-row span{color:#6f8194}.procure-summary-row strong{text-align:right;color:#17304d}.procure-progress{height:13px;background:#edf3f8;border-radius:999px;overflow:hidden}.procure-progress div{height:100%;border-radius:999px;background:linear-gradient(90deg,#168367,#31b089)}
.procure-table-panel .panel-heading{align-items:center}.procure-table-total{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.procure-table-total .panel-tag{white-space:nowrap}.procure-status{display:inline-flex;border-radius:999px;padding:3px 8px;font-size:9px;font-weight:850;border:1px solid #d9e4ef;background:#f6f9fc;color:#5d7186;white-space:nowrap}.procure-status.completed{background:#eaf8f3;border-color:#c9eadc;color:#137a61}.procure-status.pending{background:#fff6e4;border-color:#f0d6a8;color:#9b6410}.procure-status.partial{background:#eef6ff;border-color:#c9ddf6;color:#1f5fae}.procure-status.danger{background:#fff0ef;border-color:#efceca;color:#a95451}.procure-delay{font-weight:850}.procure-delay.over{color:#b35450}.procure-delay.ok{color:#168367}.procure-table .ledger th,.procure-table .ledger td{font-size:10px;padding:9px 10px!important;line-height:1.35!important}.procure-table .ledger td{vertical-align:middle!important}.procure-row-item{min-width:210px;max-width:320px;white-space:normal!important}.procure-muted{color:#8a99aa;font-size:9px;display:block;margin-top:2px}.procure-actions{display:flex;gap:7px;flex-wrap:wrap}.procure-empty{padding:30px;text-align:center;color:#8796a7;font-size:12px}.procure-empty strong{display:block;color:#425a70;font-size:15px;margin-bottom:4px}
@media(max-width:1080px){.procure-overview-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.procure-kpi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.procure-grid{grid-template-columns:1fr}.procure-filter-bar{grid-template-columns:1fr 1fr}.procure-filter-bar .procure-actions{grid-column:1/-1}}@media(max-width:680px){.procure-overview-cards,.procure-kpi-grid,.procure-filter-bar{grid-template-columns:1fr}.procure-note{display:block}.procure-note .procure-pill{display:inline-flex;margin-top:8px}}
</style>

