 if(!items.length){box.innerHTML='<div class="search-suggestions-empty">No matching customer found</div>';box.hidden=false;$('search').setAttribute('aria-expanded','true');return;}
 box.innerHTML='<div class="search-suggestions-head"><span>Customer names</span><strong>'+intFormat.format(total)+' found</strong></div>'+items.map(([name,count],i)=>'<button type="button" class="search-suggestion" role="option" data-customer-suggestion="'+esc(name)+'" data-suggestion-index="'+i+'"><span class="search-suggestion-name">'+esc(name)+'</span><span class="search-suggestion-count">'+intFormat.format(count)+' bills</span></button>').join('');
 box.hidden=false;$('search').setAttribute('aria-expanded','true');customerSuggestionIndex=-1;
}
function chooseCustomerSuggestion(name){
 $('search').value=name;state.query=name;state.page=1;hideCustomerSuggestions();render();
}
function moveCustomerSuggestion(delta){
 const box=$('customerSuggestions');if(!box||box.hidden)return false;
 const buttons=[...box.querySelectorAll('.search-suggestion')];if(!buttons.length)return false;
 customerSuggestionIndex=(customerSuggestionIndex+delta+buttons.length)%buttons.length;
 buttons.forEach((b,i)=>b.classList.toggle('active',i===customerSuggestionIndex));
 buttons[customerSuggestionIndex].scrollIntoView({block:'nearest'});return true;
}
function optionList(id,values,label){
 $(id).innerHTML='<option value="">'+esc(label)+'</option>'+[...new Set(values)].sort((a,b)=>a.localeCompare(b)).map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');
}
function initialize(raw,updated=false){
 const candidate=buildModel(raw);
 source=raw;model=candidate;
 state={...state,view:'ageing',query:'',coordinator:'',customerType:'',customer:'',bdm:'',crm:'',ageing:'',status:'',dateMode:'due',dateRange:'',dateStart:'',dateEnd:'',masterQuery:'',asof:model.snapshotDate,page:1,sortKey:'pending',sortDir:-1,procureCardFilter:''};
 optionList('coordinator',model.rows.map(r=>r.coordinator),'All coordinators');
 optionList('customerType',model.rows.map(r=>r.customerType),'All customer types');
 optionList('customer',model.rows.map(r=>r.customer),'All customers');
 optionList('bdm',model.rows.map(r=>r.bdm),'All BDMs');
 if($('crmFilter'))optionList('crmFilter',model.rows.map(r=>crmDisplayName(r.crm)),'All CRM');
 buildCustomerSuggestions();
 updateDateRangeOptions();
 $('ageing').innerHTML='<option value="">All ageing buckets</option>'+AGE_BUCKETS.map(b=>'<option value="'+b.key+'">'+b.label+'</option>').join('');
 $('asof').value=state.asof;$('unit').value=state.unit;$('search').value='';if($('masterSearch'))$('masterSearch').value='';$('status').value='';$('dateRange').value='';syncDateTopControls();
 $('snapshotBadge').textContent=(model.snapshotInferred?'Source date not found':'Source snapshot')+' \u00b7 '+displayDate(model.snapshotDate);
 $('sourceName').textContent=raw.fileName||'Receivables workbook';$('sourceName').title=raw.fileName||'';
 $('sidebarRecords').textContent=intFormat.format(model.rows.length)+' source bill rows loaded';
 $('customerNavCount').textContent=new Set(model.rows.map(r=>r.customer)).size;
 const overdueAll=datedRows().filter(r=>r.pending>0&&r.days!=null&&r.days>0);$('overdueNavCount').textContent=new Set(overdueAll.map(r=>r.customer)).size;loadPartyRemarks();loadPartyRemarkHistory();
 $('footerText').textContent='Source: Data sheet \u00b7 Offline snapshot \u00b7 No live Excel connection';
 setupProcurementControls();
 $('extraFilters').hidden=true;$('moreFilters').setAttribute('aria-expanded','false');
 render();
 if(updated)toast('Excel updated locally. Use Save dashboard copy to keep the new data.');
}

function qtyFormat(value){const n=Number(value||0);if(!Number.isFinite(n))return '0';return new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format(n);}
function procPct(num,den){num=Number(num||0);den=Number(den||0);return den?Math.round(num/den*1000)/10:0;}
function delayHtml(value){if(value==null||value==='')return '<span class="procure-delay ok">'+DASH+'</span>';const n=Number(value);const cls=n>0?'over':'ok';return '<span class="procure-delay '+cls+'">'+intFormat.format(n)+' d</span>';}
function procStatusClass(status){const s=String(status||'').toLowerCase();if(s.includes('pending'))return 'pending';if(s.includes('partial'))return 'partial';if(s.includes('reject'))return 'danger';if(s.includes('complete'))return 'completed';return '';}

function procDateDiffDays(from,to){
 if(!from||!to)return null;
 const a=Date.parse(String(from).slice(0,10)+'T00:00:00Z');
 const b=Date.parse(String(to).slice(0,10)+'T00:00:00Z');
 if(!Number.isFinite(a)||!Number.isFinite(b))return null;
 return Math.max(0,Math.round((b-a)/DAY));
}
function procGrnDone(row){return !!(clean(row.grnNo)||clean(row.grnDate)||Number(row.receivedQty||0)>0||Number(row.acceptedQty||0)>0||clean(row.qcApprovalDate));}
function procPrApproved(row){return !!(row.prApproved===true||row.prApproved==='1'||row.prApproved===1||clean(row.prApprovedDate)||clean(row.prApprovedBy)||clean(row.poNo)||clean(row.poDate)||clean(row.poApprovedDate)||procGrnDone(row));}
function procPoApproved(row){return !!(row.poApproved===true||row.poApproved==='1'||row.poApproved===1||clean(row.poApprovedDate)||clean(row.poApprovedBy)||procGrnDone(row)||clean(row.invoiceNo)||clean(row.purchaseVoucherNo));}
function procPoApprovalPending(row){return !!clean(row.poNo)&&!procPoApproved(row);}
function procPoApprovalDelay(row){
 const n=Number(row.poApprovalDelayDays||0);
 if(Number.isFinite(n)&&n>0)return n;
 const d=procDateDiffDays(row.poDate,row.poApprovedDate);
 return d&&d>0?d:0;
}
function procPoDelayed(row){return !!clean(row.poNo)&&procPoApprovalDelay(row)>0;}
function procDerivedStatus(row){
 if(!procPrApproved(row))return 'PR Approval Pending';
 if(!clean(row.poNo))return 'PO Pending';
 if(!procPoApproved(row))return 'PO Approval Pending';
 if(Number(row.receivedQty||0)<=0&&!clean(row.grnNo))return 'GRN Pending';
 if(Number(row.poQty||0)>0&&Number(row.receivedQty||0)>=Number(row.poQty||0))return 'Completed';
 if(Number(row.receivedQty||0)>0)return 'Partial GRN';
 return row.status||'GRN Pending';
}

function procCardLabel(filter){
 const labels={'total-pr':'Total PR','pr-not-approved':'PR Not Approved','total-po':'Total PO','po-not-created':'PO Not Created','po-approval-pending':'PO Approval Pending','delayed-po':'Delayed PO','total-grn':'Total GRN','grn-pending':'GRN Pending','grn-received':'Received Qty','grn-rejected':'Rejected Qty','qc-pending':'QC Pending','delayed-grn':'Delayed GRN'};
 return labels[filter]||'';
}
function procCardTargetView(filter){
 if(['total-po','po-approval-pending','delayed-po'].includes(filter))return 'po';
 if(['total-grn','grn-pending','grn-received','grn-rejected','qc-pending','delayed-grn'].includes(filter))return 'grn';
 return 'pr';
}
function procurementCardMatches(row,filter){
 if(!filter)return true;
 if(filter==='total-pr')return true;
 if(filter==='pr-not-approved')return !procPrApproved(row);
 if(filter==='total-po')return !!clean(row.poNo);
 if(filter==='po-not-created')return !clean(row.poNo);
 if(filter==='po-approval-pending')return procPoApprovalPending(row);
 if(filter==='delayed-po')return procPoDelayed(row);
 if(filter==='total-grn')return !!clean(row.grnNo)||Number(row.receivedQty||0)>0||Number(row.acceptedQty||0)>0;
 if(filter==='grn-pending')return !!clean(row.poNo)&&!procGrnDone(row);
 if(filter==='grn-received')return Number(row.receivedQty||0)>0||Number(row.acceptedQty||0)>0;
 if(filter==='grn-rejected')return Number(row.rejectedQty||0)>0;
 if(filter==='qc-pending')return (!!clean(row.grnNo)||Number(row.receivedQty||0)>0)&&!clean(row.qcApprovalDate);
 if(filter==='delayed-grn')return (!!clean(row.grnNo)||Number(row.receivedQty||0)>0)&&Number(row.grnDelayDays||0)>0;
 return true;
}
function clearProcurementFilters(kind){
 const ids=kind==='po'?['poQuery','poVendorFilter','poStatusFilter']:kind==='grn'?['grnQuery','grnVendorFilter','grnStatusFilter']:['prQuery','prDeptFilter','prStatusFilter'];
 ids.forEach(id=>{const el=$(id);if(el)el.value='';});
}
function applyProcurementCardFilter(filter){
 if(!filter)return;
 const view=procCardTargetView(filter);
 state.procureCardFilter=filter;
 clearProcurementFilters(view);
 switchView(view);
 setTimeout(()=>{const el=$(view==='po'?'poTable':view==='grn'?'grnTable':'prTable');if(el)el.scrollIntoView({block:'start',behavior:'smooth'});},80);
 toast(procCardLabel(filter)+' ka data neeche table me aa gaya.');
}
function procVisibleRows(kind){
 const q=key($(kind+'Query')?.value||'');
 const status=$(kind+'StatusFilter')?.value||'';
 const dept=$(kind+'DeptFilter')?.value||'';
 const vendor=$(kind+'VendorFilter')?.value||'';
 let rows=procurementRows.filter(r=>kind==='po'?!!clean(r.poNo):kind==='grn'?!!clean(r.poNo):true);
 if(state.procureCardFilter&&procCardTargetView(state.procureCardFilter)===kind)rows=rows.filter(r=>procurementCardMatches(r,state.procureCardFilter));
 if(status)rows=rows.filter(r=>String(procDerivedStatus(r)||r.status||'')===status);
 if(dept)rows=rows.filter(r=>String(r.department||'')===dept);
 if(vendor)rows=rows.filter(r=>String(r.party||'')===vendor);
 if(q)rows=rows.filter(r=>[r.prNo,r.poNo,r.party,r.department,r.itemType,r.itemCode,r.itemName,r.grnNo,r.invoiceNo,r.status,r.qcBy,r.purchaseVoucherNo].join(' ').toLocaleLowerCase().includes(q));
 return rows;
}
function procSelectOptions(id,values,label){const el=$(id);if(!el)return;const old=el.value;const opts=[...new Set(values.filter(v=>clean(v)))].sort((a,b)=>String(a).localeCompare(String(b)));el.innerHTML='<option value="">'+esc(label)+'</option>'+opts.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');if(opts.includes(old))el.value=old;}
function setupProcurementControls(){
 if($('prDeptFilter'))procSelectOptions('prDeptFilter',procurementRows.map(r=>r.department),'All departments');
 if($('prStatusFilter'))procSelectOptions('prStatusFilter',procurementRows.map(r=>procDerivedStatus(r)),'All status');
 const poRows=procurementRows.filter(r=>clean(r.poNo));
 const grnRows=poRows.filter(r=>procGrnDone(r));
 if($('poVendorFilter'))procSelectOptions('poVendorFilter',poRows.map(r=>r.party),'All vendors');
 if($('poStatusFilter'))procSelectOptions('poStatusFilter',poRows.map(r=>procDerivedStatus(r)),'All status');
 if($('grnVendorFilter'))procSelectOptions('grnVendorFilter',poRows.map(r=>r.party),'All vendors');
 if($('grnStatusFilter'))procSelectOptions('grnStatusFilter',poRows.map(r=>procDerivedStatus(r)),'All status');
 if($('prNavCount'))$('prNavCount').textContent=intFormat.format(procurementRows.length);
 if($('poNavCount'))$('poNavCount').textContent=intFormat.format(poRows.length);
 if($('grnNavCount'))$('grnNavCount').textContent=intFormat.format(grnRows.length);
}
function procKpi(label,value,sub,cls=''){
 return '<article class="procure-kpi '+cls+'"><span>'+esc(label)+'</span><strong>'+value+'</strong><small>'+esc(sub||'')+'</small></article>';
}

function procureTopCard(filter,label,value,sub,cls,icon){
 const active=state.procureCardFilter===filter?' active':'';
 return '<button type="button" class="procure-overview-card clickable '+(cls||'')+active+'" data-proc-card="'+esc(filter)+'" aria-label="Show '+esc(label)+' rows below"><div class="procure-overview-copy"><span>'+esc(label)+'</span><strong>'+value+'</strong><small>'+esc(sub||'')+'</small></div><div class="procure-overview-icon" aria-hidden="true"><svg class="icon"><use href="#'+esc(icon||'i-file')+'"></use></svg></div></button>';
}
function renderProcurementTopCards(targetId){
 const el=$(targetId);if(!el)return;
 const rows=procurementRows||[], poRows=rows.filter(r=>clean(r.poNo));
 const totalPr=rows.length;
 const prNotApproved=rows.filter(r=>!procPrApproved(r)).length;
 const totalPo=poRows.length;
 const poNotCreated=rows.filter(r=>!clean(r.poNo)).length;
 const poApprovalPending=poRows.filter(r=>procPoApprovalPending(r)).length;
 const delayedPo=poRows.filter(r=>procPoDelayed(r)).length;
 el.innerHTML=[
  procureTopCard('total-pr','Total PR',intFormat.format(totalPr),'PR line items; repeats included','good','i-file'),
  procureTopCard('pr-not-approved','PR Not Approved',intFormat.format(prNotApproved),'PR line items awaiting approval',prNotApproved?'danger':'good','i-clock'),
  procureTopCard('total-po','Total PO',intFormat.format(totalPo),'PO line items; repeats included','info','i-file'),
  procureTopCard('po-not-created','PO Not Created',intFormat.format(poNotCreated),intFormat.format(poNotCreated)+' line items awaiting PO creation',poNotCreated?'danger':'good','i-file'),
  procureTopCard('po-approval-pending','PO Approval Pending',intFormat.format(poApprovalPending),'PO line items awaiting approval',poApprovalPending?'warn':'good','i-clock'),
  procureTopCard('delayed-po','Delayed PO',intFormat.format(delayedPo),'PO line items with approval delay',delayedPo?'danger':'good','i-clock')
 ].join('');
}
function renderGrnSummaryCards(){
 const el=$('grnSummaryCards');if(!el)return;
 const poRows=(procurementRows||[]).filter(r=>clean(r.poNo));
 const grnRows=poRows.filter(r=>clean(r.grnNo)||Number(r.receivedQty||0)>0||Number(r.acceptedQty||0)>0);
 const pending=poRows.filter(r=>!procGrnDone(r)).length;
 const received=poRows.reduce((s,r)=>s+Math.max(Number(r.receivedQty||0),Number(r.acceptedQty||0)),0);
 const rejected=poRows.reduce((s,r)=>s+Number(r.rejectedQty||0),0);
 const qcPending=grnRows.filter(r=>!clean(r.qcApprovalDate)).length;
 const delayed=grnRows.filter(r=>Number(r.grnDelayDays||0)>0).length;
 el.innerHTML=[
  procureTopCard('total-grn','Total GRN',intFormat.format(grnRows.length),'Rows with GRN No','good','i-box'),
  procureTopCard('grn-pending','GRN Pending',intFormat.format(pending),'PO rows without GRN No',pending?'warn':'good','i-clock'),
  procureTopCard('grn-received','Received Qty',qtyFormat(received),'Total GRN / received quantity','info','i-check'),
  procureTopCard('grn-rejected','Rejected Qty',qtyFormat(rejected),'Total rejected quantity',rejected?'danger':'good','i-file'),
  procureTopCard('qc-pending','QC Pending',intFormat.format(qcPending),'GRN rows without QC approval',qcPending?'warn':'good','i-clock'),
  procureTopCard('delayed-grn','Delayed GRN',intFormat.format(delayed),'GRN rows with delay days',delayed?'danger':'good','i-clock')
 ].join('');
}
function procGroup(rows,field,measure){const m=new Map();for(const r of rows){const k=clean(r[field])||'Unassigned';m.set(k,(m.get(k)||0)+Number(r[measure]||0));}return [...m.entries()].map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value||a.name.localeCompare(b.name));}
function procCountGroup(rows,field){const m=new Map();for(const r of rows){const k=clean(r[field])||'Unassigned';m.set(k,(m.get(k)||0)+1);}return [...m.entries()].map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value||a.name.localeCompare(b.name));}
function procBars(id,groups,total,kind='normal',limit=8){const el=$(id);if(!el)return;if(!groups.length){el.innerHTML='<div class="procure-empty"><strong>No data</strong>Change filters or connect PR/PO source.</div>';return;}const max=Math.max(...groups.slice(0,limit).map(g=>Math.abs(g.value)),1);el.innerHTML=groups.slice(0,limit).map(g=>{const w=Math.max(3,Math.min(100,Math.abs(g.value)/max*100));return '<div class="procure-bar"><div class="procure-bar-label" title="'+esc(g.name)+'">'+esc(g.name)+'</div><div class="procure-bar-track"><div class="procure-bar-fill '+kind+'" style="width:'+w+'%"></div></div><div class="procure-bar-value">'+(total==='count'?intFormat.format(g.value):qtyFormat(g.value))+'</div></div>';}).join('');}
function renderPrDashboard(){
 renderProcurementTopCards('prPoSummaryCardsPr');
 const rows=procVisibleRows('pr'), all=procurementRows;
 const activeCardLabel=(state.procureCardFilter&&procCardTargetView(state.procureCardFilter)==='pr')?procCardLabel(state.procureCardFilter):'';
 const poPending=rows.filter(r=>!clean(r.poNo)).length, grnCreated=rows.filter(r=>clean(r.grnNo)).length;
 const delayRows=rows.filter(r=>Number(r.openDelayDays||0)>0||Number(r.prApprovalDelayDays||0)>0||Number(r.poCreateDelayDays||0)>0).length;
 const prQty=rows.reduce((s,r)=>s+Number(r.prQty||0),0), poQty=rows.reduce((s,r)=>s+Number(r.poQty||0),0);
 $('prSourceLabel').textContent=(procurementSource.sourceFile||'PR/PO source')+' · Sheet: '+(procurementSource.sheetName||'Sheet55')+' · As of '+displayDate(procurementSource.asOfDate||'')+' · Live receivables data is separate.';
 $('prKpis').innerHTML=[procKpi('Total PR rows',intFormat.format(rows.length),'Filtered from '+intFormat.format(all.length)+' source rows'),procKpi('PR quantity',qtyFormat(prQty),'Total PR Qty in selected rows','good'),procKpi('PO pending rows',intFormat.format(poPending),'Rows where PO No is blank',poPending?'warn':'good'),procKpi('Rows with delay',intFormat.format(delayRows),'Approval / PO creation / open delay',delayRows?'danger':'good')].join('');
 procBars('prStatusMix',procCountGroup(rows,'status'),'count','normal',8);
 procBars('prDeptMix',procGroup(rows,'department','prQty'),'qty','good',8);
 $('prTableTotal').textContent=(activeCardLabel?activeCardLabel+' · ':'')+intFormat.format(rows.length)+' rows';
 $('selectionCount').innerHTML=(activeCardLabel?'<strong>'+esc(activeCardLabel)+'</strong> · ':'')+'<strong>'+intFormat.format(rows.length)+'</strong> PR rows shown · <strong>'+intFormat.format(poPending)+'</strong> PO pending · <strong>'+intFormat.format(grnCreated)+'</strong> GRN rows';
 $('viewBasis').textContent='Separate PR/PO Sheet55 source · Receivables live sheet is not modified';
 if(!rows.length){$('prTable').innerHTML='<div class="procure-empty"><strong>No PR rows found</strong>Try clearing PR filters.</div>';return;}
 const body=rows.slice(0,250).map(r=>'<tr><td>'+esc(r.prNo||DASH)+'<span class="procure-muted">Row '+intFormat.format(r.row)+'</span></td><td>'+esc(displayDate(r.prDate))+'</td><td>'+esc(r.department||DASH)+'</td><td class="procure-row-item">'+esc(r.itemName||DASH)+'<span class="procure-muted">'+esc([r.itemCode,r.itemType].filter(Boolean).join(' · '))+'</span></td><td class="num">'+qtyFormat(r.prQty)+'</td><td>'+esc(r.poNo||DASH)+'<span class="procure-muted">'+esc(r.party||'')+'</span></td><td><span class="procure-status '+procStatusClass(procDerivedStatus(r))+'">'+esc(procDerivedStatus(r)||DASH)+'</span></td><td>'+esc(displayDate(r.prApprovedDate))+'</td><td class="num">'+delayHtml(r.poCreateDelayDays)+'</td><td class="num">'+delayHtml(r.openDelayDays)+'</td></tr>').join('');
 $('prTable').innerHTML='<table class="ledger"><thead><tr><th>PR No</th><th>PR Date</th><th>Department</th><th>Item</th><th class="num">PR Qty</th><th>PO No / Vendor</th><th>Status</th><th>PR Approved</th><th class="num">PO Delay</th><th class="num">Open Delay</th></tr></thead><tbody>'+body+'</tbody></table>'+(rows.length>250?'<div class="table-bottom">Showing first 250 rows. Use search/filter or Export PR CSV for full data.</div>':'');
}
