 const poQty=rows.reduce((s,r)=>s+Number(r.poQty||0),0), grnQty=rows.reduce((s,r)=>s+Number(r.receivedQty||0),0), rejected=rows.reduce((s,r)=>s+Number(r.rejectedQty||0),0), pending=rows.reduce((s,r)=>s+Number(r.pendingQty||0),0);
 const grnPending=rows.filter(r=>r.status==='GRN Pending').length, completed=rows.filter(r=>String(r.status||'').includes('Completed')).length;
 $('poSourceLabel').textContent=(procurementSource.sourceFile||'PR/PO source')+' · Sheet: '+(procurementSource.sheetName||'Sheet55')+' · As of '+displayDate(procurementSource.asOfDate||'')+' · Live receivables data is separate.';
 $('poKpis').innerHTML=[procKpi('PO rows',intFormat.format(rows.length),'Filtered from '+intFormat.format(all.length)+' PO rows'),procKpi('PO Qty',qtyFormat(poQty),'Total ordered quantity','good'),procKpi('GRN / Received Qty',qtyFormat(grnQty),procPct(grnQty,poQty)+'% of PO Qty','good'),procKpi('Pending Qty',qtyFormat(pending),'PO Qty minus received quantity',pending?'warn':'good')].join('');
 const pct=procPct(grnQty,poQty), pendingPct=procPct(pending,poQty), rejectPct=procPct(rejected,poQty);
