/* Due-date ageing. All amounts remain integer paise until display/export.
   Future due dates and missing due dates are explicit, separate buckets. */
function ageingStats(rows){
 const map=new Map(AGE_BUCKETS.map(b=>[b.key,{...b,pending:0,gross:0,credit:0,count:0,open:0,customers:new Set(),openCustomers:new Set()}]));
 for(const r of rows){const b=map.get(ageKey(r.days));b.pending+=r.pending;b.count++;b.customers.add(r.customer);if(r.pending>0){b.gross+=r.pending;b.open++;b.openCustomers.add(r.customer);}else if(r.pending<0)b.credit+=r.pending;}
 return [...map.values()];
}
function ageingCustomers(rows){
 const map=new Map();
 for(const r of rows){
  if(!map.has(r.customer))map.set(r.customer,{name:r.customer,pending:0,open:0,count:0,owners:new Set(),types:new Set(),buckets:Object.fromEntries(AGE_BUCKETS.map(b=>[b.key,0])),bucketCounts:Object.fromEntries(AGE_BUCKETS.map(b=>[b.key,0]))});
  const a=map.get(r.customer),k=ageKey(r.days);a.pending+=r.pending;a.count++;if(r.pending>0)a.open++;a.owners.add(r.coordinator);a.types.add(r.customerType);a.buckets[k]+=r.pending;a.bucketCounts[k]++;
 }
 return [...map.values()].map(a=>{for(const b of AGE_BUCKETS)a['age_'+b.key]=a.buckets[b.key];return a;});
}
function ageExportDownload(headers,values,stem){
 const csv='\ufeff'+[headers,...values].map(row=>row.map(csvCell).join(',')).join('\r\n');
 downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),stem+'_'+state.asof+'.csv');
 toast(intFormat.format(values.length)+' rows exported. Monetary values are INR rupees.');
}
