 values.push(['TOTAL',m.pending/100,m.gross/100,m.credit/100,m.open,currentRows.length,m.allCustomers,state.asof,model.snapshotDate,'Distinct customers in total; bucket customer counts are not additive']);
 ageExportDownload(headers,values,'Basik_ageing_summary');
}
