 const values=rows.map(a=>[a.name,[...a.owners].join(' / '),[...a.types].join(' / '),a.pending/100,...AGE_BUCKETS.map(b=>a.buckets[b.key]/100),a.open,a.count,state.asof,model.snapshotDate,'Due date; 0 means due today; 365+ means 366 and above']);
