 $('ageOtherBuckets').innerHTML=contextStats.filter(b=>['notdue','unknown'].includes(b.key)).map(b=>'<button class="age-other-bucket '+(state.ageing===b.key?'is-selected':'')+'" data-age="'+b.key+'" aria-pressed="'+(state.ageing===b.key)+'"><span class="legend-dot" style="background:'+b.color+'"></span><span><strong>'+b.label+'</strong><small>'+(b.key==='notdue'?'Future due dates only':'Cannot calculate days')+' &middot; '+intFormat.format(b.open)+' open bill rows</small></span><b title="'+esc(fullMoney(b.pending))+'">'+money(b.pending)+'</b></button>').join('');
 $('ageReconciliation').innerHTML=icon('check')+'<span><strong>Every source row enters exactly one bucket.</strong> Six day ranges + Not yet due + Due date missing = net outstanding. Due today is in 0 - 30 days, but not in overdue. 365+ means 366 days or more.</span>';
 $('ageSummaryContext').textContent='Current selection | '+(state.unit==='lakh'?'INR lakh':state.unit==='crore'?'INR crore':'INR rupees')+' | Negative balances shown in brackets';
 const td=(p)=>'<td class="num '+(p<0?'negative':'')+'" title="'+esc(fullMoney(p))+'">'+money(p)+'</td>';
 const summaryRows=stats.map(b=>'<tr class="'+(state.ageing===b.key?'selected-bucket-row':'')+'"><td><button class="link-button" data-bucket-bills="'+b.key+'" title="Show bills for '+b.label+'"><span class="legend-dot" style="background:'+b.color+';margin-right:8px"></span>'+b.label+'</button></td>'+td(b.pending)+td(b.gross)+td(b.credit)+'<td class="num">'+intFormat.format(b.open)+'</td><td class="num">'+intFormat.format(b.count)+'</td><td class="num">'+intFormat.format(b.customers.size)+'</td></tr>').join('');
 $('ageSummaryTable').innerHTML='<table class="ledger age-summary"><thead><tr><th>Ageing bucket</th><th class="num">Net outstanding</th><th class="num">Positive balance</th><th class="num">Credit balance</th><th class="num">Open bill rows</th><th class="num">Source rows</th><th class="num">Customers*</th></tr></thead><tbody>'+summaryRows+'</tbody><tfoot><tr><td>Total selected</td>'+td(m.pending)+td(m.gross)+td(m.credit)+'<td class="num">'+intFormat.format(m.open)+'</td><td class="num">'+intFormat.format(currentRows.length)+'</td><td class="num">'+intFormat.format(m.allCustomers)+'</td></tr></tfoot></table>';
 renderAgeingCustomerTable(stats);
