function renderAgeingCustomerTable(stats){
 const all=sorted(ageingCustomers(currentRows)),rows=pageSlice(all);
 const columns=AGE_BUCKETS.filter(b=>b.key!=='unknown'||stats.find(s=>s.key==='unknown').count||state.ageing==='unknown');
 $('ageCustomerCount').textContent=intFormat.format(all.length)+' CUSTOMERS';
 if(!rows.length){$('ageCustomerTable').innerHTML=emptyMessage();renderPagination('ageCustomerPagination',0);return;}
 const head=th('Customer','name')+th('Net outstanding','pending',true)+columns.map(b=>th(b.short+(b.key==='notdue'||b.key==='unknown'?'':' days'),'age_'+b.key,true)).join('')+th('Open rows','open',true);
 const body=rows.map(a=>'<tr><td class="customer-cell"><button class="link-button" data-drill-customer="'+esc(a.name)+'">'+esc(a.name)+'</button><span class="subline">'+esc([...a.owners].join(' / '))+'</span></td><td class="num total-column '+(a.pending<0?'negative':'')+'" title="'+esc(fullMoney(a.pending))+'">'+money(a.pending)+'</td>'+columns.map(b=>'<td class="num '+(a.buckets[b.key]<0?'negative':'')+'">'+(a.bucketCounts[b.key]?'<button class="matrix-value '+(a.buckets[b.key]<0?'negative':'')+'" data-age-customer="'+esc(a.name)+'" data-age-bucket="'+b.key+'" title="'+esc(a.name+' | '+b.label+' | '+fullMoney(a.buckets[b.key])+' | '+a.bucketCounts[b.key]+' source rows')+'">'+(a.buckets[b.key]?money(a.buckets[b.key]):DASH)+'</button>':'<span class="no-balance">'+DASH+'</span>')+'</td>').join('')+'<td class="num">'+intFormat.format(a.open)+'</td></tr>').join('');
 const footer='<tr><td>All filtered customers <span class="subline">All pages, not just this page</span></td><td class="num" title="'+esc(fullMoney(currentMetrics.pending))+'">'+money(currentMetrics.pending)+'</td>'+columns.map(b=>{const p=stats.find(s=>s.key===b.key).pending;return '<td class="num '+(p<0?'negative':'')+'" title="'+esc(fullMoney(p))+'">'+money(p)+'</td>';}).join('')+'<td class="num">'+intFormat.format(currentMetrics.open)+'</td></tr>';
 $('ageCustomerTable').innerHTML='<table class="ledger ageing-matrix"><thead><tr>'+head+'</tr></thead><tbody>'+body+'</tbody><tfoot>'+footer+'</tfoot></table>';
 renderPagination('ageCustomerPagination',all.length);
}

function renderOverview(){
 const m=currentMetrics;
 const groups=weeklyPriorityGroups(weeklySnapshotGroups(currentRows)).slice(0,7).sort((a,b)=>a.start.localeCompare(b.start));
 $('rmsWeeklyBars').innerHTML=rmsWeeklyBarsSvg(groups);
 const bucketValues={
  '0-30':0,'31-60':0,'61-90':0,'91-180':0,'>180':0
 };
 for(const r of currentRows){
  if(r.pending<=0)continue;
  const k=ageKey(r.days);
  if(k==='0-30')bucketValues['0-30']+=r.pending;
  else if(k==='31-60')bucketValues['31-60']+=r.pending;
  else if(k==='61-90')bucketValues['61-90']+=r.pending;
  else if(k==='91-180')bucketValues['91-180']+=r.pending;
  else if(k==='181-365'||k==='365+')bucketValues['>180']+=r.pending;
 }
 $('rmsAgeDonut').innerHTML=rmsAgeingDonutHtml(bucketValues);
 const top=currentCustomers.filter(c=>c.overdue>0).sort((a,b)=>b.overdue-a.overdue).slice(0,5);
 $('rmsTopOverdueTable').innerHTML=top.length?'<table class="rms-table"><thead><tr><th>#</th><th>Customer</th><th class="num">Overdue (₹)</th></tr></thead><tbody>'+top.map((c,i)=>'<tr><td>'+intFormat.format(i+1)+'</td><td><button class="link-button" data-drill-customer="'+esc(c.name)+'">'+esc(c.name)+'</button></td><td class="num">'+money(c.overdue)+'</td></tr>').join('')+'</tbody></table>':'<div class="rms-empty">No overdue customer in selected data.</div>';
 const activities=currentRows.map(r=>{
  let date=r.receiptDate||r.billDate||r.dueDate||'';
  let activity='Invoice Added',cls='blue',amount=r.pending;
  if(r.receipt>0){activity='Payment Received';cls='green';amount=r.receipt;date=r.receiptDate||date;}
  else if(r.cnIssued>0){activity='Credit Note Issued';cls='orange';amount=r.cnIssued;}
  else if(r.rtv>0){activity='RTV Updated';cls='orange';amount=r.rtv;}
  else if(r.days!=null&&r.days>0){activity='Follow up';cls='orange';}
  return {date,customer:r.customer,activity,cls,amount};
 }).filter(x=>x.date).sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,5);
 $('rmsRecentActivities').innerHTML=activities.length?'<table class="rms-table"><thead><tr><th>Date</th><th>Customer</th><th>Activity</th><th class="num">Amount</th></tr></thead><tbody>'+activities.map(a=>'<tr><td>'+esc(displayDate(a.date))+'</td><td>'+esc(a.customer)+'</td><td class="'+a.cls+'">'+esc(a.activity)+'</td><td class="num">'+(a.amount?money(a.amount):DASH)+'</td></tr>').join('')+'</tbody></table>':'<div class="rms-empty">No recent activity found for selected filters.</div>';
 const alerts=currentRows.filter(r=>r.pending>0&&r.days!=null&&r.days>0).sort((a,b)=>(b.days-a.days)||(b.pending-a.pending)).slice(0,5);
 $('rmsAlertsTable').innerHTML=alerts.length?'<table class="rms-table"><thead><tr><th>Customer</th><th>Due Date</th><th class="num">Overdue (Days)</th><th class="num">Amount</th></tr></thead><tbody>'+alerts.map(r=>'<tr><td><button class="link-button" data-drill-customer="'+esc(r.customer)+'">'+esc(r.customer)+'</button></td><td>'+esc(displayDate(r.dueDate))+'</td><td class="num red">'+intFormat.format(r.days)+'</td><td class="num">'+money(r.pending)+'</td></tr>').join('')+'</tbody></table>':'<div class="rms-empty">No overdue alerts in selected data.</div>';
}
function rmsWeeklyBarsSvg(groups){
 const rows=[...groups];
 if(!rows.length)return '<div class="rms-empty">No weekly data available.</div>';
 const W=700,H=230,L=48,R=14,T=18,B=38,plotW=W-L-R,plotH=H-T-B;
 const max=Math.max(...rows.flatMap(g=>[g.ttlOverdue||0,g.receipt||0]),1);
 const step=plotW/rows.length,barW=Math.min(28,step*.28);
 let grid='',bars='',labels='';
 for(let i=0;i<=4;i++){const y=T+plotH*i/4;const val=max*(1-i/4);grid+='<line x1="'+L+'" y1="'+y+'" x2="'+(W-R)+'" y2="'+y+'" stroke="#e6eef7"/><text x="'+(L-8)+'" y="'+(y+3)+'" text-anchor="end" font-size="10" fill="#637b96">'+esc(compactMoney(val))+'</text>';}
 rows.forEach((g,i)=>{const cx=L+step*i+step/2;const due=Math.max(1,plotH*(g.ttlOverdue||0)/max);const rec=Math.max(1,plotH*(g.receipt||0)/max);bars+='<rect x="'+(cx-barW-3)+'" y="'+(T+plotH-due)+'" width="'+barW+'" height="'+due+'" rx="4" fill="#127cff"/><rect x="'+(cx+3)+'" y="'+(T+plotH-rec)+'" width="'+barW+'" height="'+rec+'" rx="4" fill="#18b66a"/>';labels+='<text x="'+cx+'" y="'+(H-14)+'" text-anchor="middle" font-size="10" fill="#244361">'+esc(weeklyLabel(g).replace('Week-','W'))+'</text>';});
 return '<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Week-wise due versus received">'+grid+bars+labels+'</svg>';
}
function rmsAgeingDonutHtml(values){
 const labels=[
  {k:'0-30',label:'0-30 Days',color:'#127cff'},
  {k:'31-60',label:'30-60 Days',color:'#17b66a'},
  {k:'61-90',label:'61-90 Days',color:'#ffc01d'},
  {k:'91-180',label:'91-180 Days',color:'#ff7d13'},
  {k:'>180',label:'>180 Days',color:'#ff2e3a'}
 ];
 const totalVal=labels.reduce((s,l)=>s+(values[l.k]||0),0);
 if(totalVal<=0)return '<div class="rms-empty">No positive ageing balance found.</div>';
 const circ=2*Math.PI*62;let offset=0;
 const circles=labels.map(l=>{const v=values[l.k]||0;const len=v/totalVal*circ;const out='<circle cx="82" cy="82" r="62" fill="none" stroke="'+l.color+'" stroke-width="24" stroke-dasharray="'+len+' '+(circ-len)+'" stroke-dashoffset="'+(-offset)+'"/>';offset+=len;return out;}).join('');
 const legend=labels.map(l=>{const v=values[l.k]||0;return '<div><i style="background:'+l.color+'"></i><span>'+esc(l.label)+'</span><strong>'+percent(v,totalVal)+'</strong></div>';}).join('');
 return '<div class="rms-age-centre"><svg viewBox="0 0 164 164" aria-label="Ageing distribution"><circle cx="82" cy="82" r="62" fill="none" stroke="#eef4fb" stroke-width="24"/>'+circles+'</svg><div class="donut-center"><strong>'+money(totalVal)+'</strong><span>Total</span></div></div><div class="rms-age-legend">'+legend+'</div>';
}

function performanceRows(tab){
 if(tab==='customers')return currentCustomers.filter(r=>r.pending!==0).sort((a,b)=>b.pending-a.pending).slice(0,10).map((r,i)=>({rank:i+1,title:r.name,sub:[...r.owners].join(' / ')||'Unassigned',v1:money(r.pending),v1Title:fullMoney(r.pending),v2:money(r.overdue),v2Title:fullMoney(r.overdue),v3:intFormat.format(r.open),action:'customer',actionValue:r.name}));
 if(tab==='owners')return aggregate(currentRows,'coordinator').sort((a,b)=>b.pending-a.pending).slice(0,10).map((r,i)=>({rank:i+1,title:r.name,sub:intFormat.format(r.count)+' bill rows',v1:money(r.pending),v1Title:fullMoney(r.pending),v2:money(r.overdue),v2Title:fullMoney(r.overdue),v3:intFormat.format(r.open),action:'owner',actionValue:r.name}));
 if(tab==='types')return aggregate(currentRows,'customerType').sort((a,b)=>b.pending-a.pending).slice(0,10).map((r,i)=>({rank:i+1,title:r.name,sub:intFormat.format(r.count)+' bill rows',v1:money(r.pending),v1Title:fullMoney(r.pending),v2:money(r.overdue),v2Title:fullMoney(r.overdue),v3:intFormat.format(r.open),action:'none',actionValue:''}));
 if(tab==='crm')return aggregate(currentRows,'crm').sort((a,b)=>b.pending-a.pending).slice(0,10).map((r,i)=>({rank:i+1,title:r.name||'Unassigned CRM',sub:[...r.owners].join(' / ')||'No owner mapped',v1:money(r.pending),v1Title:fullMoney(r.pending),v2:money(r.overdue),v2Title:fullMoney(r.overdue),v3:intFormat.format(r.open),action:'crm',actionValue:r.name||'Unassigned CRM'}));
 if(tab==='ageing')return ageingStats(currentRows).filter(b=>b.gross||b.pending||b.count).sort((a,b)=>b.gross-a.gross).map((r,i)=>({rank:i+1,title:r.label,sub:intFormat.format(r.open)+' open bills · '+intFormat.format(r.customers.size)+' customers',v1:money(r.pending),v1Title:fullMoney(r.pending),v2:money(r.gross),v2Title:fullMoney(r.gross),v3:percent(r.gross,currentMetrics.gross),action:'age',actionValue:r.key}));
 return [];
}
