}

function renderRank(id,field,isOverdue){
 const rows=currentCustomers.filter(a=>a[field]>0).sort((a,b)=>b[field]-a[field]).slice(0,5);
 const max=rows[0]?.[field]||1;
 $(id).innerHTML=rows.length?rows.map((r,i)=>'<button class="rank-item '+(isOverdue?'overdue':'')+'" data-drill-customer="'+esc(r.name)+'" title="'+esc(r.name+' | '+fullMoney(r[field])+' | Click to see bills')+'"><span class="rank-number">'+(i+1)+'</span><span><span class="rank-name">'+esc(r.name)+'</span><span class="rank-track"><span class="rank-fill" style="width:'+(r[field]/max*100).toFixed(3)+'%"></span></span></span><strong class="rank-value">'+money(r[field])+'</strong></button>').join(''):emptyMessage('No positive balances in this selection.');
}
const emptyMessage=(s='Try another search or reset your filters.')=>'<div class="empty"><strong>No matching records</strong>'+esc(s)+'</div>';
function sorted(rows){
 return [...rows].sort((a,b)=>{let av=a[state.sortKey],bv=b[state.sortKey];if(av==null)av=typeof bv==='number'?-Infinity:'';if(bv==null)bv=typeof av==='number'?-Infinity:'';const r=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv));return r*state.sortDir||String(a.name||a.customer||'').localeCompare(String(b.name||b.customer||''))||(a.row||0)-(b.row||0);});
}
function th(label,field,numeric=false){
 const active=state.sortKey===field;return '<th class="'+(numeric?'num':'')+'" aria-sort="'+(active?(state.sortDir===1?'ascending':'descending'):'none')+'"><button data-sort="'+field+'">'+esc(label)+'<span class="sort-arrow">'+(active?(state.sortDir===1?'\u2191':'\u2193'):'\u2195')+'</span></button></th>';
}
function pageSlice(rows){const pages=Math.max(1,Math.ceil(rows.length/state.pageSize));state.page=Math.min(Math.max(1,state.page),pages);return rows.slice((state.page-1)*state.pageSize,state.page*state.pageSize);}
function renderPagination(id,count){
 const pages=Math.max(1,Math.ceil(count/state.pageSize));
 $(id).innerHTML='<span>'+ (count?'Showing '+intFormat.format((state.page-1)*state.pageSize+1)+' - '+intFormat.format(Math.min(state.page*state.pageSize,count))+' of '+intFormat.format(count):'No records')+' \u00b7 Net total <strong>'+money(currentMetrics.pending)+'</strong></span><div class="page-controls"><label for="'+id+'Size">Rows</label><select id="'+id+'Size" data-page-size>'+[25,50,100].map(n=>'<option value="'+n+'" '+(state.pageSize===n?'selected':'')+'>'+n+'</option>').join('')+'</select><button class="page-button" data-page="-1" '+(state.page<=1?'disabled':'')+' aria-label="Previous page">\u2039</button><span>'+state.page+' / '+pages+'</span><button class="page-button" data-page="1" '+(state.page>=pages?'disabled':'')+' aria-label="Next page">\u203a</button></div>';
}
function normalizeSourceForMaster(){
 if(!Array.isArray(source.headers))source.headers=[];
 if(!Array.isArray(source.rows))source.rows=[];
 source.headers=source.headers.map(h=>clean(h)||'Column');
 const width=source.headers.length;
 source.rows=source.rows.map((item,idx)=>{
  const rowNumber=Number(item&&item.row)||idx+4;
  const v=Array.isArray(item&&item.v)?item.v.slice(0,width):[];
  while(v.length<width)v.push('');
  return {row:rowNumber,v};
 });
}
function masterRowsFiltered(){
 normalizeSourceForMaster();
 const q=key(state.masterQuery||'');
 const rows=source.rows.map((item,sourceIndex)=>({sourceIndex,row:Number(item.row)||0,v:Array.isArray(item.v)?item.v:[]}));
 if(!q)return rows;
 return rows.filter(item=>item.v.some(v=>key(v).includes(q))||String(item.row).includes(q));
}
function masterCell(value){
 if(value==null)return '';
 return esc(String(value));
}
function setMasterDirty(flag=true,message){
 masterDirty=!!flag;
 const el=$('masterDirtyState');
 if(el){el.textContent=message||(masterDirty?'Unsaved changes':'Saved');el.classList.toggle('unsaved',masterDirty);}
}
function refreshMasterColumnSelect(){
 const sel=$('masterColumnSelect');if(!sel)return;
 const headers=Array.isArray(source.headers)?source.headers:[];
 if(masterSelectedColumn<0||masterSelectedColumn>=headers.length)masterSelectedColumn=0;
 sel.innerHTML=headers.length?headers.map((h,i)=>'<option value="'+i+'" '+(i===masterSelectedColumn?'selected':'')+'>'+(i+1)+'. '+esc(h||'(Blank header)')+'</option>').join(''):'<option value="">No columns</option>';
}
function selectedMasterIndexes(){
 return [...document.querySelectorAll('.master-row-check:checked')].map(el=>Number(el.value)).filter(Number.isInteger);
}
function nextMasterRowNumber(){
 const nums=(source.rows||[]).map(r=>Number(r.row)||0);
 return Math.max(3,...nums)+1;
}
function renderMasterPagination(count){
 const pages=Math.max(1,Math.ceil(count/state.pageSize));state.page=Math.min(Math.max(1,state.page),pages);
 $('masterPagination').innerHTML='<span>'+(count?'Showing '+intFormat.format((state.page-1)*state.pageSize+1)+' - '+intFormat.format(Math.min(state.page*state.pageSize,count))+' of '+intFormat.format(count)+' source rows':'No source rows')+' · '+intFormat.format((source.headers||[]).length)+' columns <span class="master-deleted-hint">Select rows to delete or duplicate</span></span><div class="page-controls"><label for="masterPaginationSize">Rows</label><select id="masterPaginationSize" data-page-size>'+[25,50,100].map(n=>'<option value="'+n+'" '+(state.pageSize===n?'selected':'')+'>'+n+'</option>').join('')+'</select><button class="page-button" data-page="-1" '+(state.page<=1?'disabled':'')+' aria-label="Previous page">‹</button><span>'+state.page+' / '+pages+'</span><button class="page-button" data-page="1" '+(state.page>=pages?'disabled':'')+' aria-label="Next page">›</button></div>';
}

