 download('crm_wise_summary.csv',lines.join('\n'),'text/csv');
}

function renderMasterData(){
 normalizeSourceForMaster();
 const headers=source.headers;
 const all=masterRowsFiltered();
 const pages=Math.max(1,Math.ceil(all.length/state.pageSize));state.page=Math.min(Math.max(1,state.page),pages);
 const rows=all.slice((state.page-1)*state.pageSize,state.page*state.pageSize);
 const fileName=source.fileName||'Receivables workbook';
 $('masterFileName').textContent=fileName;$('masterFileName').title=fileName;
 $('masterRowCount').textContent=intFormat.format((source.rows||[]).length);
 $('masterColumnCount').textContent=intFormat.format(headers.length);
 $('masterCustomerCount').textContent=intFormat.format(new Set(model.rows.map(r=>r.customer)).size);
 $('masterTotal').textContent=intFormat.format(all.length)+' ROWS';
 refreshMasterColumnSelect();
 setMasterDirty(masterDirty);
 if(!headers.length){$('masterTable').innerHTML=emptyMessage('No columns are available. Click Add Column to create a field.');renderMasterPagination(all.length);return;}
 if(!rows.length){$('masterTable').innerHTML=emptyMessage(state.masterQuery?'No rows match the Master Data search.':'No uploaded source data is available. Click Add Row to create one.');renderMasterPagination(all.length);return;}
 const head='<th><input type="checkbox" id="masterSelectAll" class="master-row-check" aria-label="Select all visible rows"></th><th>Row</th>'+headers.map((h,i)=>'<th class="master-col-head '+(i===masterSelectedColumn?'active':'')+'" data-master-col-head="'+i+'" title="Click to select column '+esc(h)+'">'+esc(h||'(Blank header)')+'</th>').join('');
 const body=rows.map(item=>'<tr data-source-index="'+item.sourceIndex+'"><td><input type="checkbox" class="master-row-check" value="'+item.sourceIndex+'" aria-label="Select source row '+esc(item.row)+'"></td><td class="master-rownum">'+intFormat.format(item.row)+'</td>'+headers.map((h,i)=>'<td class="master-edit-cell" contenteditable="true" spellcheck="false" data-master-row="'+item.sourceIndex+'" data-master-col="'+i+'" title="Edit '+esc(h)+'">'+masterCell(item.v[i])+'</td>').join('')+'</tr>').join('');
 $('masterTable').innerHTML='<table class="master-table"><thead><tr>'+head+'</tr></thead><tbody>'+body+'</tbody></table>';
 renderMasterPagination(all.length);
}
function addMasterRow(){
 normalizeSourceForMaster();
 const width=source.headers.length;
 if(!width){toast('Pehle Add Column se columns create karein.',true);return;}
 source.rows.push({row:nextMasterRowNumber(),v:Array(width).fill('')});
 state.masterQuery='';if($('masterSearch'))$('masterSearch').value='';
 state.page=Math.max(1,Math.ceil(source.rows.length/state.pageSize));
 setMasterDirty(true,'Unsaved: row added');
 renderMasterData();
}
function duplicateMasterRows(){
 normalizeSourceForMaster();
 const selected=selectedMasterIndexes();
 if(!selected.length){toast('Duplicate karne ke liye row select karein.',true);return;}
 const rows=selected.map(i=>source.rows[i]).filter(Boolean);
 let next=nextMasterRowNumber();
 for(const r of rows){source.rows.push({row:next++,v:(r.v||[]).slice()});}
 state.masterQuery='';if($('masterSearch'))$('masterSearch').value='';
 state.page=Math.max(1,Math.ceil(source.rows.length/state.pageSize));
 setMasterDirty(true,'Unsaved: row duplicated');
 renderMasterData();
}
function deleteMasterRows(){
 normalizeSourceForMaster();
 const selected=selectedMasterIndexes().sort((a,b)=>b-a);
 if(!selected.length){toast('Delete karne ke liye row select karein.',true);return;}
 if(!confirm(selected.length+' selected row delete karni hai?'))return;
 for(const i of selected){if(source.rows[i])source.rows.splice(i,1);}
 setMasterDirty(true,'Unsaved: row deleted');
 renderMasterData();
}
function addMasterColumn(){
 normalizeSourceForMaster();
 let name=prompt('New column name:','New Column');
 if(name==null)return;
 name=clean(name);
 if(!name){toast('Column name blank nahi ho sakta.',true);return;}
 source.headers.push(name);
 for(const r of source.rows)r.v.push('');
 masterSelectedColumn=source.headers.length-1;
 setMasterDirty(true,'Unsaved: column added');
 renderMasterData();
}
function renameMasterColumn(){
 normalizeSourceForMaster();
 if(!source.headers.length){toast('No column to rename.',true);return;}
 const idx=Number($('masterColumnSelect')?.value ?? masterSelectedColumn);
 if(!Number.isInteger(idx)||idx<0||idx>=source.headers.length){toast('Column select karein.',true);return;}
 let name=prompt('Rename column:',source.headers[idx]||'');
 if(name==null)return;
 name=clean(name);
 if(!name){toast('Column name blank nahi ho sakta.',true);return;}
 source.headers[idx]=name;
 masterSelectedColumn=idx;
 setMasterDirty(true,'Unsaved: column renamed');
 renderMasterData();
}
function deleteMasterColumn(){
 normalizeSourceForMaster();
 if(source.headers.length<=1){toast('At least one column required.',true);return;}
 const idx=Number($('masterColumnSelect')?.value ?? masterSelectedColumn);
 if(!Number.isInteger(idx)||idx<0||idx>=source.headers.length){toast('Column select karein.',true);return;}
 if(!confirm('Column "'+source.headers[idx]+'" delete karni hai?'))return;
 source.headers.splice(idx,1);
 for(const r of source.rows)r.v.splice(idx,1);
 masterSelectedColumn=Math.max(0,Math.min(idx,source.headers.length-1));
 setMasterDirty(true,'Unsaved: column deleted');
 renderMasterData();
}
async function saveMasterData(){
 normalizeSourceForMaster();
 if(!source.headers.length){toast('No columns to save.',true);return;}
 const hasCustomer=source.headers.some(h=>['party','customer name','customer','party name'].includes(key(h)));
 const hasPending=source.headers.some(h=>['pending amount','pending amt','outstanding amount','balance amount'].includes(key(h)));
 if(!hasCustomer||!hasPending){toast('Save blocked: Customer/Party aur Pending Amount column required hai.',true);return;}
 const btn=$('masterSaveBtn');if(btn){btn.disabled=true;btn.textContent='Saving...';}
 try{
  source={...source,fileName:source.fileName||'Master Data',rows:source.rows,headers:source.headers,sourceHeaderTotal:null,legacyTotal:null,legacyRangeEnd:null};
  if(window.serverSaveImportedData){await window.serverSaveImportedData(source);}else{model=buildModel(source);setMasterDirty(false,'Saved in browser');render();toast('Master Data saved in browser copy.');}
 }catch(e){console.error(e);toast('Master save failed: '+(e.message||e),true);if(btn){btn.disabled=false;btn.textContent='Save Master Data';}}
}
