function statusOf(r){if(r.pending===0)return {label:'Settled',className:'settled'};if(r.pending<0)return {label:'Credit',className:'credit'};if(r.days==null)return {label:'Due date missing',className:''};if(r.days>0)return {label:'Overdue',className:'overdue'};return {label:r.days===0?'Due today':'Not due',className:'notdue'};}
function billFollowupValue(r){return clean(r.actionPoint)||clean(r.action)||'';}
function sourceHeaderKey(name){return key(name).replace(/\s+/g,' ');}
function sourceHeaderIndex(names){
 const wanted=names.map(sourceHeaderKey);
 return (source.headers||[]).findIndex(h=>wanted.includes(sourceHeaderKey(h)));
}
function ensureSourceHeader(headerName){
 normalizeSourceForMaster();
 let idx=sourceHeaderIndex([headerName,'Action Point','Action / follow-up','Follow up','Follow-up','Followup']);
 if(idx>=0)return idx;
 source.headers.push(headerName);
 for(const r of source.rows||[])r.v.push('');
 return source.headers.length-1;
}
function updateSourceFollowup(rowNumber,value){
 normalizeSourceForMaster();
 const idx=ensureSourceHeader('Action Point');
 const row=(source.rows||[]).find(r=>Number(r.row)===Number(rowNumber));
 if(!row)throw new Error('Source row '+rowNumber+' not found. Please sync/import again.');
 while(row.v.length<source.headers.length)row.v.push('');
 const old=row.v[idx]??'';
 row.v[idx]=value;
 return {old,header:source.headers[idx]||'Action Point'};
}
function billFollowupInput(rowNumber){return [...document.querySelectorAll('[data-bill-followup]')].find(el=>String(el.dataset.billFollowup)===String(rowNumber));}
function startBillFollowupEdit(rowNumber){
 const input=billFollowupInput(rowNumber);if(!input)return;
 input.readOnly=false;input.focus();input.selectionStart=input.selectionEnd=input.value.length;
 input.classList.add('unsaved');input.dataset.dirty='1';
}
async function saveBillFollowup(rowNumber,button=null,clear=false){
 const input=billFollowupInput(rowNumber);if(!input)return;
 const value=clear?'':input.value.trim();
 const rowId=Number(rowNumber);
 const snapshot=JSON.parse(JSON.stringify(source));
 if(button){button.disabled=true;button.textContent=clear?'Clearing...':'Saving...';}
 try{
  updateSourceFollowup(rowId,value);
  let result=null;
  if(window.serverSaveBillFollowup)result=await window.serverSaveBillFollowup({row:rowId,value});
  else if(window.serverSaveImportedData)await window.serverSaveImportedData(source);
  model=buildModel(source);
  input.value=value;input.readOnly=true;input.classList.remove('unsaved');input.dataset.dirty='';
  render();
  if(result&&result.googleSynced)toast('Follow-up saved and Google Sheet updated.');
  else if(result&&result.googleMessage)toast('Follow-up saved in portal. Google Sheet update pending: '+result.googleMessage,true);
  else toast('Follow-up saved.');
 }catch(e){
  source=snapshot;
  try{model=buildModel(source);}catch(_e){}
  console.error(e);toast('Follow-up save failed: '+(e.message||e),true);
 }finally{
  if(button){button.disabled=false;button.textContent=clear?'Clear':'Save';}
 }
}
function clearBillFollowup(rowNumber,button=null){
 if(!confirm('Clear follow-up for Data row '+rowNumber+'? Customer/invoice data safe rahega.'))return;
 const input=billFollowupInput(rowNumber);if(input)input.value='';
 saveBillFollowup(rowNumber,button,true);
}
