function isoFromUtcDate(d){return d.toISOString().slice(0,10);}
function isoAddDays(iso,delta){const n=day(iso);return Number.isFinite(n)?isoFromUtcDate(new Date((n+delta)*DAY)):iso;}
function monthWeekRange(iso){
 const n=day(iso);if(!Number.isFinite(n))return null;
 const d=new Date(n*DAY),y=d.getUTCFullYear(),m=d.getUTCMonth(),dom=d.getUTCDate();
 const week=dom<=7?1:dom<=14?2:dom<=21?3:4;
 const startDay=week===1?1:week===2?8:week===3?15:22;
 const lastDay=new Date(Date.UTC(y,m+1,0)).getUTCDate();
 const endDay=week===4?lastDay:startDay+6;
 return {start:isoFromUtcDate(new Date(Date.UTC(y,m,startDay))),end:isoFromUtcDate(new Date(Date.UTC(y,m,endDay))),week,year:y,month:m};
}
function monthWeekRangesForPeriod(rows=weeklyBaseRows()){
 // Week-wise Summary deliberately ignores the page's From/To filter so the user
 // can compare every management week in the available receivables history.
 const dateCandidates=[];
 for(const r of rows){
  [r.billDate,r.receiptDate,r.dueDate,r.cnDate,r.rtvDate,r.rightOffDate,r.otherDate].forEach(d=>{if(dateInBusinessRange(d))dateCandidates.push(d);});
 }
 const asof=dateInBusinessRange(state.asof,'2020-01-01',BUSINESS_DATE_MAX)?state.asof:(dateInBusinessRange(model.snapshotDate,'2020-01-01',BUSINESS_DATE_MAX)?model.snapshotDate:todayIso());
 let startIso=dateCandidates.length?dateCandidates.sort()[0]:asof;
 const asofN=day(asof),asofD=new Date(asofN*DAY);
 const endIso=isoFromUtcDate(new Date(Date.UTC(asofD.getUTCFullYear(),asofD.getUTCMonth()+1,0)));
 if(startIso>endIso)startIso=isoFromUtcDate(new Date(Date.UTC(asofD.getUTCFullYear(),asofD.getUTCMonth(),1)));
 const startD=new Date(day(startIso)*DAY),endD=new Date(day(endIso)*DAY);
 let y=startD.getUTCFullYear(),m=startD.getUTCMonth();
 const ey=endD.getUTCFullYear(),em=endD.getUTCMonth();
 const out=[];
 while(y<ey||(y===ey&&m<=em)){
  const last=new Date(Date.UTC(y,m+1,0)).getUTCDate();
  for(const [week,a,b] of [[1,1,7],[2,8,14],[3,15,21],[4,22,last]]){
   const s=isoFromUtcDate(new Date(Date.UTC(y,m,a))),e=isoFromUtcDate(new Date(Date.UTC(y,m,b)));
   if(e>=startIso&&s<=endIso)out.push({start:s,end:e,week,year:y,month:m});
  }
  m++;if(m>11){m=0;y++;}
  if(out.length>800)break;
 }
 return out;
}
function weeklyBaseRows(){
 const q=key(state.query);
 return model.rows.filter(r=>{
  if(state.coordinator&&r.coordinator!==state.coordinator)return false;
  if(state.customerType&&r.customerType!==state.customerType)return false;
  if(state.customer&&r.customer!==state.customer)return false;
  if(state.bdm&&r.bdm!==state.bdm)return false;
  if(q&&![r.customer,r.ref,r.coordinator,r.customerType,r.bdm,r.city,r.contact,r.email,r.remarks,r.jayaRemarks,r.action,r.actionPoint,r.osType,r.targetWeek].join(' ').toLocaleLowerCase().includes(q))return false;
  return true;
 });
}
function balanceAsOf(r,iso){
 if(!r.billDate||r.billDate>iso)return 0;
 let value=Math.max(0,r.oldPending||0);
 // Debit Note date is not guaranteed in the source. Credit Note is tracked separately in weekly collections.
 const cnDate=r.cnDate||null;
 const debitAmt=Math.max(0,r.debit||0);
 if(debitAmt>0&&(!cnDate||cnDate<=iso))value-=debitAmt;
 const rec=Math.max(0,r.receipt||0);
 if(rec>0&&(!r.receiptDate||r.receiptDate<=iso))value-=rec;
 return Math.max(0,value);
}
function datedAmountInRange(amount,date,start,end,fallbackDate){
 const n=Math.max(0,amount||0);if(!n)return 0;
 const d=date||fallbackDate||state.asof;
 return d>=start&&d<=end?n:0;
}
function weeklyMetricsForRange(rows,w){
 const prev=isoAddDays(w.start,-1);
 let ttlOS=0,ttlOverdue=0,receipt=0,cnIssued=0,rtv=0,rightOff=0,other=0,bmSum=0,bmCount=0;
 const parties=new Set();let openBills=0;
 for(const r of rows){
  const openingBal=balanceAsOf(r,prev);
  if(openingBal>0){ttlOS+=openingBal;openBills++;parties.add(r.customer);if(r.dueDate&&r.dueDate<=prev)ttlOverdue+=openingBal;}
  receipt+=datedAmountInRange(r.receipt,r.receiptDate,w.start,w.end,null);
  cnIssued+=datedAmountInRange(r.cnIssued,r.cnDate,w.start,w.end,r.receiptDate);
  rtv+=datedAmountInRange(r.rtv,r.rtvDate,w.start,w.end,r.receiptDate);
  rightOff+=datedAmountInRange(r.rightOff,r.rightOffDate,w.start,w.end,r.receiptDate);
  other+=datedAmountInRange(r.other,r.otherDate,w.start,w.end,r.receiptDate);
  if(Number.isFinite(r.bm)){bmSum+=r.bm;bmCount++;}
 }
 const totalCollected=receipt+cnIssued+rtv+rightOff+other;
 const denom=ttlOverdue>0?ttlOverdue:ttlOS;
 return {...w,ttlOS,ttlOverdue,receipt,cnIssued,rtv,rightOff,other,totalCollected,collectionPct:denom>0?receipt/denom*100:null,bmPct:bmCount?bmSum/bmCount:WEEKLY_BM_DEFAULT,openBills,parties};
}
function weeklySnapshotGroups(rows=weeklyBaseRows()){
 const ranges=monthWeekRangesForPeriod(rows);
 return ranges.map(w=>weeklyMetricsForRange(rows,w));
}
function weeklySelectedPeriod(){
 if(state.dateStart&&state.dateEnd)return {start:state.dateStart,end:state.dateEnd,custom:true};
 const current=monthWeekRange(state.asof)||{start:state.asof,end:state.asof};
 return {...current,custom:false};
}
function weeklyPriorityGroups(groups){
 const asof=state.asof||model.snapshotDate;
 const curYM=String(asof||'').slice(0,7);
 const rank=g=>{
  const ym=String(g.start||'').slice(0,7);
  if(ym===curYM){
   if(g.start<=asof&&g.end>=asof)return 0; // current week first
   if(g.end<asof)return 1;                 // recent overdue/past weeks next
   return 2;                               // upcoming weeks of current month after past
  }
  if(g.end<asof)return 3;                  // older months below current month
  return 4;                                // future months last
 };
 return [...groups].sort((a,b)=>{
  const ra=rank(a),rb=rank(b);
  if(ra!==rb)return ra-rb;
  if(ra===1||ra===3)return b.start.localeCompare(a.start); // newest past first
  if(ra===2||ra===4)return a.start.localeCompare(b.start); // nearest future first
  return b.start.localeCompare(a.start);
 });
}
function weeklyLabel(g){
 const d=new Date(Date.UTC(g.year,g.month,1));
 return d.toLocaleString('en-US',{month:'short',timeZone:'UTC'})+'- Week-'+g.week;
}
function pctText(v){return Number.isFinite(v)?v.toFixed(0)+'%':DASH;}
function weeklyStatus(g,current){
 if(g.start<=state.asof&&g.end>=state.asof)return {label:'Current week',cls:'notdue'};
 if(g.end<state.asof)return {label:'Past week',cls:'settled'};
 return {label:'Upcoming',cls:'notdue'};
}
