 $('weeklyPagination').innerHTML='<span>'+(count?'Showing '+intFormat.format((state.page-1)*state.pageSize+1)+' - '+intFormat.format(Math.min(state.page*state.pageSize,count))+' of '+intFormat.format(count)+' weeks':'No weeks')+'</span><div class="page-controls"><label for="weeklyPaginationSize">Rows</label><select id="weeklyPaginationSize" data-page-size>'+[25,50,100].map(n=>'<option value="'+n+'" '+(state.pageSize===n?'selected':'')+'>'+n+'</option>').join('')+'</select><button class="page-button" data-page="-1" '+(state.page<=1?'disabled':'')+' aria-label="Previous page">\u2039</button><span>'+state.page+' / '+pages+'</span><button class="page-button" data-page="1" '+(state.page>=pages?'disabled':'')+' aria-label="Next page">\u203a</button></div>';
