function weeklyTrendSvg(groups){
 const rows=[...groups].sort((a,b)=>a.start.localeCompare(b.start)).slice(-8);
 if(!rows.length)return '<div class="empty"><strong>No trend data</strong>Historical weekly data is not available for the current selection.</div>';
 const W=820,H=245,L=58,R=16,T=16,B=44,plotW=W-L-R,plotH=H-T-B;
 const max=Math.max(...rows.flatMap(g=>[g.ttlOS,g.receipt,g.ttlOverdue]),1);
 const y=v=>T+plotH-(v/max)*plotH;
 const step=plotW/rows.length,barW=Math.min(26,step*.25);
 let grid='';for(let i=0;i<=4;i++){const yy=T+plotH*i/4;const val=max*(1-i/4);grid+='<line x1="'+L+'" y1="'+yy+'" x2="'+(W-R)+'" y2="'+yy+'" stroke="#e8eef5" stroke-width="1"/><text x="'+(L-8)+'" y="'+(yy+3)+'" text-anchor="end" font-size="9" fill="#8495a8">'+esc(compactMoney(val))+'</text>';}
 let bars='',labels='',pts=[];
 rows.forEach((g,i)=>{const cx=L+step*i+step/2;const h1=Math.max(1,plotH*g.ttlOS/max),h2=Math.max(1,plotH*g.receipt/max);bars+='<rect x="'+(cx-barW-2)+'" y="'+(T+plotH-h1)+'" width="'+barW+'" height="'+h1+'" rx="3" fill="#2f7df4" opacity=".92"/><rect x="'+(cx+2)+'" y="'+(T+plotH-h2)+'" width="'+barW+'" height="'+h2+'" rx="3" fill="#22b36f" opacity=".9"/>';pts.push(cx+','+y(g.ttlOverdue));labels+='<text x="'+cx+'" y="'+(H-17)+'" text-anchor="middle" font-size="8.5" fill="#61778f">'+esc(weeklyLabel(g).replace('Week-','W'))+'</text>';});
 const poly=pts.length>1?'<polyline points="'+pts.join(' ')+'" fill="none" stroke="#f05b68" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>':'';
 const dots=rows.map((g,i)=>{const cx=L+step*i+step/2,cy=y(g.ttlOverdue);return '<circle cx="'+cx+'" cy="'+cy+'" r="3.2" fill="#f05b68" stroke="#fff" stroke-width="1.3"/>';}).join('');
 return '<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Week-wise outstanding, received and overdue trend">'+grid+bars+poly+dots+labels+'</svg>';
}
function compactMoney(v){const n=Math.abs((v||0)/100);if(n>=10000000)return (n/10000000).toFixed(n>=100000000?0:1)+'Cr';if(n>=100000)return (n/100000).toFixed(n>=1000000?0:1)+'L';if(n>=1000)return (n/1000).toFixed(0)+'K';return numberFormat.format(n);}
function weeklyDonutHtml(g){
 const os=Math.max(0,g?.ttlOS||0),received=Math.max(0,g?.receipt||0),adj=Math.max(0,(g?.cnIssued||0)+(g?.rtv||0)+(g?.rightOff||0)+(g?.other||0));
 const collected=Math.min(os,received+adj),balance=Math.max(0,os-collected),p=os?Math.min(100,collected/os*100):0,recP=os?Math.min(100,received/os*100):0,adjP=os?Math.min(100,adj/os*100):0;
 const grad='conic-gradient(#2f7df4 0 '+recP.toFixed(2)+'%,#22b36f '+recP.toFixed(2)+'% '+Math.min(100,recP+adjP).toFixed(2)+'%,#edf1f6 '+Math.min(100,recP+adjP).toFixed(2)+'% 100%)';
 return {html:'<div class="weekly-donut" style="background:'+grad+'"><div class="weekly-donut-center"><strong>'+p.toFixed(0)+'%</strong><span>Collected</span></div></div>',legend:'<div><span><i style="background:#2f7df4"></i>Received</span><b>'+money(received)+'</b></div><div><span><i style="background:#22b36f"></i>Credit Note / RTV / Write-off / Other</span><b>'+money(adj)+'</b></div><div><span><i style="background:#edf1f6;border:1px solid #dce4ed"></i>Balance</span><b>'+money(balance)+'</b></div>'};
}
