async function addPartyContact(party,kind,button=null){
 const existing=manualContactRecord(party);
 const rowInfo=(partyRemarkRows().find(x=>x.name===party)||{});
 const currentPhone=existing.contact||firstValue(rowInfo.contacts)||'';
 const currentEmail=existing.email||firstValue(rowInfo.emails)||'';
 const currentCity=existing.city||firstValue(rowInfo.cities)||'';
 let patch={};
 if(kind==='mail'){
  const value=prompt('Email add/update karo for '+party, currentEmail);
  if(value===null)return;
  const email=clean(value);
  if(email&&!looksLikeEmail(email)){toast('Valid email address enter karo.',true);return;}
  patch.email=email;
 }else{
  const value=prompt('WhatsApp / Mobile number add/update karo for '+party, currentPhone);
  if(value===null)return;
  const contact=clean(value);
  if(contact&&!normalizePhoneNumber(contact)){toast('Valid mobile/WhatsApp number enter karo.',true);return;}
  patch.contact=contact;
 }
 const city=prompt('City optional hai. Blank chhod sakte ho.', currentCity);
 if(city!==null)patch.city=clean(city);
 if(button){button.disabled=true;button.textContent='Saving...';}
 try{
  const rec={party,city:patch.city!==undefined?patch.city:currentCity,contact:patch.contact!==undefined?patch.contact:currentPhone,email:patch.email!==undefined?patch.email:currentEmail};
  if(window.serverSavePartyContact){
   const result=await window.serverSavePartyContact(rec);
   setManualContactRecord(party,result.contact||rec);
  }else{
   setManualContactRecord(party,rec);
  }
  model=buildModel(source);
  state.page=1;
  render();
  toast('Contact details saved for '+party+'.');
 }catch(e){
  toast('Contact save failed: '+(e.message||'Server error'),true);
 }finally{
  if(button){button.disabled=false;button.textContent=kind==='mail'?'+ Add Mail':'+ Add WhatsApp';}
 }
}

