 const contact=clean(phoneValue);
 if(contact&&!normalizePhoneNumber(contact)){toast('Valid mobile/WhatsApp number enter karo.',true);return;}
 const emailValue=prompt('Email change karo for '+party, currentEmail);
 if(emailValue===null)return;
 const email=clean(emailValue);
 if(email&&!looksLikeEmail(email)){toast('Valid email address enter karo.',true);return;}
 const cityValue=prompt('City change karo. Blank chhod sakte ho.', currentCity);
 if(cityValue===null)return;
 const city=clean(cityValue);
 if(button){button.disabled=true;button.textContent='Saving...';}
 try{
  const rec={party,city,contact,email};
  if(window.serverSavePartyContact){
   const result=await window.serverSavePartyContact(rec);
   setManualContactRecord(party,result.contact||rec);
  }else{
   setManualContactRecord(party,rec);
  }
  model=buildModel(source);
  render();
  toast('Contact details updated for '+party+'.');
 }catch(e){
  toast('Contact update failed: '+(e.message||'Server error'),true);
 }finally{
  if(button){button.disabled=false;button.textContent='Edit Contact';}
 }
}


function renderPartyRemarks(){
 const all=partyRemarkRows(),rows=pageSlice(all);
 const crmCount=new Set(all.map(partyCrmLabel)).size;
 $('remarksTotal').textContent=intFormat.format(all.length)+' PARTIES · '+intFormat.format(crmCount)+' CRM';
 if(!rows.length){$('remarksTable').innerHTML=emptyMessage();renderPagination('remarksPagination',0);return;}
 const sourceByParty=new Map();for(const r of selectedRows()){const t=[r.remarks,r.jayaRemarks].filter(Boolean).join(' | ');if(t)sourceByParty.set(r.customer,t);}
 const crmTotals=new Map();for(const r of all){const crm=partyCrmLabel(r);const x=crmTotals.get(crm)||{count:0,pending:0,overdue:0};x.count++;x.pending+=r.pending;x.overdue+=r.overdue;crmTotals.set(crm,x);}
 const head='<th>Party</th><th>CRM</th><th>Coordinator</th><th>City</th><th>Contact</th><th class="num">Net O/S</th><th class="num">Overdue</th><th class="num">Oldest DPD</th><th>Source remark</th><th>Party wise remark</th><th>Action</th><th>Send</th>';
 let lastCrm='';
 const body=rows.map(r=>{
  const val=partyRemarks[r.name]||'', encoded=esc(r.name), hCount=(partyRemarkHistory[r.name]||[]).length;
  const crm=partyCrmLabel(r), crmInfo=crmTotals.get(crm)||{count:0,pending:0,overdue:0};
  const crmGroup=crm!==lastCrm?'<tr class="crm-group-row"><td colspan="12"><span class="crm-group-title">CRM: '+esc(crm)+' <span class="crm-group-count">'+intFormat.format(crmInfo.count)+' parties</span><span class="crm-group-count">O/S '+money(crmInfo.pending)+'</span><span class="crm-group-count">Overdue '+money(crmInfo.overdue)+'</span></span></td></tr>':'';
  lastCrm=crm;
  const city=firstValue(r.cities)||'', phone=firstValue(r.contacts)||'', email=firstValue(r.emails)||'';
  const wa=whatsappRemarkUrl(phone,r.name,r.pending,r.overdue), mail=emailRemarkUrl(email,r.name,r.pending,r.overdue);
  const editContactButton='<button type="button" class="contact-edit-btn" data-edit-contact="'+encoded+'">Edit Contact</button>';
  const contactCell='<span class="remark-contact-main">'+esc(phone||DASH)+'</span>'+(email?'<span class="remark-contact-sub">'+esc(email)+'</span>':'')+editContactButton;
  const sendCell='<div class="remark-send-actions">'+contactActionHtml('whatsapp',wa,'WhatsApp',r.name)+contactActionHtml('mail',mail,'Mail',r.name)+'</div><span class="send-hint">Customer Master se contact/email pick hota hai</span>';
  return crmGroup+'<tr><td class="customer-cell"><button class="link-button" data-drill-customer="'+encoded+'">'+esc(r.name)+'</button><span class="subline">'+esc([...r.types].join(' / '))+'</span></td><td class="crm-cell"><span class="crm-chip '+(crm==='Unassigned CRM'?'unassigned':'')+'">'+esc(crm)+'</span></td><td>'+esc([...r.owners].join(' / '))+'</td><td class="remark-contact-cell">'+esc(city||DASH)+'</td><td class="remark-contact-cell">'+contactCell+'</td><td class="num" title="'+esc(fullMoney(r.pending))+'">'+money(r.pending)+'</td><td class="num" title="'+esc(fullMoney(r.overdue))+'">'+money(r.overdue)+'</td><td class="num">'+(r.maxDays==null?DASH:intFormat.format(r.maxDays))+'</td><td class="source-remark">'+esc(sourceByParty.get(r.name)||DASH)+'</td><td class="party-remark-cell"><textarea class="remark-input" data-party-remark="'+encoded+'" placeholder="Follow-up / commitment / next action..." readonly>'+esc(val)+'</textarea><span class="remark-meta '+(val?'server-saved remark-saved':'')+'">'+(val?'Saved':'Click Edit to add remark')+'</span></td><td><div class="remark-actions"><button type="button" class="remark-action" data-remark-edit="'+encoded+'">Edit</button><button type="button" class="remark-action save" data-remark-save="'+encoded+'">Save</button><button type="button" class="remark-action delete" data-remark-delete="'+encoded+'">Clear Remark</button><button type="button" class="remark-action remark-history-btn" data-remark-history="'+encoded+'">History'+(hCount?'<span class="remark-history-badge">'+hCount+'</span>':'')+'</button></div></td><td class="send-after-action">'+sendCell+'</td></tr>';
 }).join('');
 $('remarksTable').innerHTML='<table class="ledger"><thead><tr>'+head+'</tr></thead><tbody>'+body+'</tbody></table>';renderPagination('remarksPagination',all.length);
}

function remarkTextareaForParty(party){
 const escaped=(window.CSS&&CSS.escape)?CSS.escape(party):party.replace(/(["'\\.#:[\],>+~*^$|=])/g,'\\$1');
 return document.querySelector('[data-party-remark="'+escaped+'"]');
}
function setRemarkMeta(textarea,message,mode=''){
 const meta=textarea?.nextElementSibling;if(!meta)return;
 meta.textContent=message;
 meta.classList.toggle('remark-saved',mode==='saved');
 meta.classList.toggle('server-saved',mode==='saved');
 meta.classList.toggle('unsaved',mode==='unsaved');
 meta.classList.toggle('error',mode==='error');
}
function markPartyRemarkUnsaved(textarea){
 textarea.dataset.dirty='1';
 setRemarkMeta(textarea,'Unsaved - Save button click karein','unsaved');
}
async function savePartyRemarkManual(party,button=null){
 const textarea=remarkTextareaForParty(party);if(!textarea)return;
 const value=textarea.value.trim();
 if(button){button.disabled=true;button.textContent='Saving...';}
 try{
  if(value)partyRemarks[party]=value;else delete partyRemarks[party];
  persistPartyRemarks();
  let result=null;if(window.serverSavePartyRemark)result=await window.serverSavePartyRemark(party,value);
  if(result&&result.history)addPartyRemarkHistory(party,result.history);
  textarea.dataset.dirty='';textarea.readOnly=true;
  setRemarkMeta(textarea,value?'Saved':'Cleared / blank','saved');
  if(state.view==='remarks')renderPartyRemarks();
  toast((result&&result.changed===false?'No change in remark for ':'Remark saved for ')+party+'.');
 }catch(e){
  setRemarkMeta(textarea,e.message||'Save failed','error');
  toast('Remark save failed: '+(e.message||'Server error'),true);
 }finally{
  if(button){button.disabled=false;button.textContent='Save';}
 }
}
async function deletePartyRemarkManual(party,button=null){
 const textarea=remarkTextareaForParty(party);if(!textarea)return;
 if(!confirm('Clear remark for '+party+'? Only the remark will be removed, customer data will stay safe.'))return;
 textarea.value='';
 await savePartyRemarkManual(party,button);
}
async function saveVisiblePartyRemarks(){
 const list=[...document.querySelectorAll('#remarksTable [data-party-remark]')].filter(el=>el.dataset.dirty==='1');
 if(!list.length){toast('No unsaved visible remarks.');return;}
 for(const el of list)await savePartyRemarkManual(el.dataset.partyRemark);
 toast(list.length+' visible remark(s) saved.');
}

function addPartyRemarkHistory(party,entry){
 if(!entry)return;
 if(!partyRemarkHistory[party])partyRemarkHistory[party]=[];
 const id=entry.id?String(entry.id):'';
 if(id&&partyRemarkHistory[party].some(x=>String(x.id)===id))return;
 partyRemarkHistory[party].unshift(entry);
 if(partyRemarkHistory[party].length>20)partyRemarkHistory[party]=partyRemarkHistory[party].slice(0,20);
}
function formatHistoryTime(value){
 if(!value)return DASH;
 const d=new Date(String(value).replace(' ','T'));
 if(Number.isNaN(d.getTime()))return value;
 return d.toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
}
function showPartyRemarkHistory(party){
 const dialog=$('remarkHistoryDialog'),body=$('remarkHistoryBody'),title=$('remarkHistoryTitle');if(!dialog||!body)return;
 title.textContent='Remark history - '+party;
 const list=partyRemarkHistory[party]||[];
 if(!list.length){body.innerHTML='<div class="remark-history-empty">No remark history found for this party yet.</div>';dialog.showModal();return;}
 body.innerHTML='<div class="remark-history-list">'+list.map(item=>{
  const action=clean(item.action||'update');
  return '<div class="remark-history-item"><div class="remark-history-top"><span class="remark-history-action">'+esc(action)+'</span><span class="remark-history-time">'+esc(formatHistoryTime(item.at))+'</span></div><div class="remark-history-grid"><div class="remark-history-box"><b>Old remark</b>'+(item.old?esc(item.old):DASH)+'</div><div class="remark-history-box"><b>New remark</b>'+(item.new?esc(item.new):DASH)+'</div></div><div class="remark-history-by">Changed by: <strong>'+esc(item.by||'System')+'</strong></div></div>';
 }).join('')+'</div>';
 dialog.showModal();
}
