 const excelCss='body{font-family:Arial,sans-serif;font-size:12px}table{border-collapse:collapse;width:100%}th{background:#06213d;color:#fff;font-weight:700}th,td{border:1px solid #d8e2ee;padding:6px 8px;text-align:left}.num{text-align:right}';
 const html='<!doctype html><html><head><meta charset="utf-8"><style>'+excelCss+'</style></head><body>'+table+'</body></html>';
 downloadBlob(new Blob(['\ufeff'+html],{type:'application/vnd.ms-excel;charset=utf-8'}),fileName);
}
