  const html='<!doctype html><html><head><meta charset="utf-8"><style>'+excelCss+'</style></head><body>'+clone.outerHTML+'</body></html>';
  downloadBlob(new Blob(['\ufeff'+html],{type:'application/vnd.ms-excel;charset=utf-8'}),'Basik_'+state.view+'_'+state.asof+'.xls');
