 const values=currentRows.map(r=>[r.row,r.ref,r.customer,r.customerType,r.coordinator,r.billDate,r.dueDate,r.pending/100,statusOf(r).label,state.asof]);
 htmlTableDownload(headers,values,'Basik_dashboard_'+state.asof+'.xls');toast('Dashboard records exported to Excel.');
