function renderChecks(){
 const q=model.issues,whole=model.rows.map(r=>({...r,days:r.dueDate?day(model.snapshotDate)-day(r.dueDate):null})),m=metrics(whole);
 const headerMatch=model.sourceHeaderTotal!=null&&Math.abs(model.sourceHeaderTotal-model.pending)<=1;
 const critical=q.missingPending.length+q.unparsedFinancial.length+q.balanceMismatches.length;
 let html='<section class="checks-intro"><div><h2>'+icon('check')+' '+(critical?'Imported with review items':'Complete source coverage, reconciled balances')+'</h2><p>'+intFormat.format(model.rows.length)+' bill rows from Data, rows '+Math.min(...model.rows.map(r=>r.row))+' - '+Math.max(...model.rows.map(r=>r.row))+'. '+intFormat.format(m.allCustomers)+' customer names after whitespace normalization. No duplicate references were silently removed.<br>All values below use the source snapshot date: '+displayDate(model.snapshotDate)+'.</p></div></section>';
 html+='<div class="check-tiles"><div class="check-tile"><small>COMPLETE DATA TOTAL</small><strong>'+money(model.pending)+'</strong><p>'+esc(fullMoney(model.pending))+' \u00b7 all valid bill rows</p></div><div class="check-tile"><small>STORED DATA!K1 TOTAL</small><strong>'+(model.sourceHeaderTotal==null?DASH:money(model.sourceHeaderTotal))+'</strong><p>'+(headerMatch?'Matches the complete imported total.':model.sourceHeaderTotal==null?'No saved header total available.':'Differs from import. Header may use filters or stale formulas.')+'</p></div><div class="check-tile"><small>ROWS BEYOND LEGACY RANGE</small><strong>'+(model.legacyEnd?intFormat.format(model.beyond.length):DASH)+'</strong><p>'+(model.legacyEnd?'Beyond row '+model.legacyEnd+' \u00b7 '+money(model.beyondPending)+' included.':'No legacy dashboard range detected.')+'</p></div></div>';
 const line=(title,body,good=false)=>'<div class="check-item"><span class="check-pill '+(good?'good':'')+'">'+(good?'CHECKED':'REVIEW')+'</span><div><strong>'+esc(title)+'</strong>'+body+'</div></div>';
 html+='<section class="checks-section"><h3>Source issues and handling</h3>';
 if(model.legacyEnd&&model.beyond.length)html+=line('Old dashboard range ended at Data!K'+model.legacyEnd,'The original DASHBOARD!A6 total was '+esc(model.legacyTotal==null?DASH:fullMoney(model.legacyTotal))+'. This HTML includes '+model.beyond.length+' later bill rows, adding '+esc(fullMoney(model.beyondPending))+'. Summary sheets are not added to the bill data, which avoids double-counting.');
 html+=line(q.duplicates.length+' repeated customer + bill reference group'+(q.duplicates.length===1?'':'s'),q.duplicates.length?q.duplicates.map(d=>esc(d.customer)+' \u00b7 '+esc(d.ref)+' \u00b7 rows '+d.rows.join(', ')+' \u00b7 combined pending '+esc(fullMoney(d.pending))+'. Both rows are retained; verify against the ledger.').join('<br>'):'No repeated customer/reference combination found.',!q.duplicates.length);
 html+=line(q.recovered.length+' rows enriched from Customer Master','Missing or error-valued classification fields were filled only when an exact customer-name match existed in Customer Master. Only whitespace in customer names is normalized; spelling, branches and financial rows are otherwise retained. No fuzzy customer matching is used. '+(q.recovered.length?'Recovered source rows: '+q.recovered.map(x=>x.row).join(', ')+'.':''),true);
 if(q.nameVariants.length)html+=line(q.nameVariants.length+' whitespace-only customer-name group normalized',q.nameVariants.map(g=>'Name: '+esc(g.name)+'. '+g.variants.length+' spacing variants are shown together; all source rows and amounts remain included. Original spelling is retained in the bill CSV.').join('<br>'),true);
 html+=line(q.targetErrors.length+' Collection Target lookup errors','The optional Data!T field contains '+q.targetErrors.length+' lookup errors. They are displayed as unavailable in bill details, not treated as collection amounts. This field is not used to calculate pending or overdue totals.',!q.targetErrors.length);
 html+=line(q.balanceMismatches.length+' pending formula mismatches','Each row uses G - I - J when all needed financial inputs are valid; otherwise the saved Pending Amount is used. '+(q.balanceMismatches.length?'Affected rows: '+q.balanceMismatches.map(x=>x.row).join(', ')+'. The recomputed values are used in this dashboard.':'Saved pending amounts agree with the source inputs wherever both are present.')+(q.derivedPending.length?' '+q.derivedPending.length+' missing cached pending values were reconstructed.':''),!q.balanceMismatches.length);
 html+=line(q.missingDue.length+' rows without usable due dates',q.missingDue.length?'These rows remain in net outstanding and appear in the Due date missing bucket; they are not labelled overdue or not-due.':'Every imported bill row has a due date. No outstanding amount is left outside the ageing reconciliation.',!q.missingDue.length);
 if(q.missingPending.length)html+=line(q.missingPending.length+' rows excluded: no usable pending amount','Affected source rows: '+q.missingPending.map(r=>r.row).join(', ')+'. Review these before treating totals as complete.');
 if(q.unparsedFinancial.length)html+=line('Unparseable financial components','Source rows '+q.unparsedFinancial.map(r=>r.row).join(', ')+' use saved pending balances. Invalid receipt/debit components are not included in component summaries; review the source.');
 html+=line('Open-bill and customer counts','Open bills are positive source bill rows, not distinct invoice references. Customers with open bills counts distinct names with at least one positive row. Zero/settled and credit rows remain available in the register.',true);
 html+='</section>';
 const buckets=AGE_BUCKETS.map(b=>({...b,rows:whole.filter(r=>ageKey(r.days)===b.key)}));
 html+='<section class="checks-section"><h3>Non-overlapping ageing reconciliation</h3><p>Due date &lt; snapshot date is overdue. Due today is not overdue, but it is day 0 in the 0 - 30 ageing bucket. Not yet due means a future due date. Exactly 365 days belongs to 181 - 365; 365+ starts at day 366. All rows, including zero and negative balances, enter exactly one bucket.</p><table class="data-check-table"><thead><tr><th>Days past due</th><th>Source rows</th><th>Net pending (INR)</th></tr></thead><tbody>'+buckets.map(b=>'<tr><td>'+b.label+'</td><td>'+b.rows.length+'</td><td>'+fullMoney(total(b.rows,'pending'))+'</td></tr>').join('')+'<tr class="total"><td>Total</td><td>'+model.rows.length+'</td><td>'+fullMoney(model.pending)+'</td></tr></tbody></table></section>';
 html+='<section class="checks-section"><h3>Calculation and scope</h3><div class="formula-box">Net outstanding = OLD Pending Amount - Debit Note - Receipt Amount<br>TDS = optional imported reference amount; it is displayed separately and does not change Net outstanding<br>Overdue (net) = sum of pending where Due Date &lt; ageing date<br>Not due / today (net) = sum of pending where Due Date &gt;= ageing date<br>Gross receivables + negative credit balances = net outstanding</div><p style="margin-top:12px">The exposure donut alone uses positive (gross) balances. KPI amounts, customer rankings, owner/type tables and ageing bars use net pending amounts including credits. Amounts are calculated in integer paise and only rounded for display.</p><p>Overview receipts are the amounts recorded in the selected Data rows. The Week-wise Summary uses Receipt Date to place receipts into the correct management week and reconstructs opening outstanding from OLD Pending, Debit Note, Credit Note and dated receipts. If an adjustment amount has no dedicated date, Receipt Date is used as its fallback allocation date. REPORT, OS Working, Santosh S and Jaya are supporting/summary sheets, not additional invoices.</p><p>Changing the ageing date changes classification only. It does not undo past receipts or import new payments. Use Update Excel for fresh balances, then Save dashboard copy to persist them. This file makes no network requests.</p></section>';
 $('checksContent').innerHTML=html;
}
function drillCustomer(name){state.customer=name;$('customer').value=name;state.view='bills';state.page=1;state.sortKey='pending';state.sortDir=-1;render();window.scrollTo({top:0,behavior:'smooth'});}
function showBill(row){
