 $('detailTitle').textContent=r.ref;const s=statusOf(r);
 const pair=(label,value)=>'<div class="detail-item"><small>'+esc(label)+'</small><strong>'+esc(value)+'</strong></div>';
 const values=[['Source row','Data!'+r.row],['Customer (source spelling)',r.customerRaw],['Coordinator',r.coordinator],['Customer type',r.customerType],['BDM',r.bdm],['CRM',r.crm],['Balance status',s.label],['Bill date',displayDate(r.billDate)],['Due date',displayDate(r.dueDate)],['Days past due',r.days==null?DASH:String(r.days)],['Ageing bucket',bucketLabel(ageKey(r.days))],['Credit terms',r.terms==null?DASH:r.terms+' days'],['Opening amount',r.opening==null?DASH:fullMoney(r.opening)],['Old pending amount',fullMoney(r.oldPending)],['Debit note',fullMoney(r.debit)],['Recorded receipt',fullMoney(r.receipt)],['TDS',fullMoney(r.tds)],['Net pending',fullMoney(r.pending)],['Receipt date',displayDate(r.receiptDate)],['Target date',displayDate(r.targetDate)],['Target week',r.targetWeek||DASH],['Collection Target field',r.collectionTarget||DASH],['Week 1 target (recorded)',r.weeklyTarget==null?DASH:fullMoney(r.weeklyTarget)],['Week 1 received (recorded)',r.weeklyReceived==null?DASH:fullMoney(r.weeklyReceived)]];
 let html='<div class="detail-customer">'+esc(r.customer)+'</div><span class="badge '+s.className+'">'+s.label+'</span>'+(r.duplicate?'<div class="notice warning" style="margin-top:15px">Repeated customer + bill reference. This row is retained separately; verify it against the ledger.</div>':'')+'<div class="detail-grid">'+values.map(v=>pair(v[0],v[1])).join('')+'</div>';
 [['Action type',r.action],['Action point',r.actionPoint],['Focus follow-ups',r.focus],['Remarks',r.remarks],['Jaya remarks',r.jayaRemarks],['OS type',r.osType],['Delivery status',r.delivery],['Credit Note field',r.creditNote],['Additional type',r.shortType]].forEach(([l,v])=>{if(v)html+='<div class="detail-block"><b>'+esc(l)+'</b>'+esc(v)+'</div>';});
 if(r.repairs.length)html+='<div class="notice" style="margin-top:15px">Recovered from Customer Master: '+esc(r.repairs.join(', '))+'.</div>';
 $('detailBody').innerHTML=html;$('detailDialog').showModal();
}
function toast(message,error=false){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.toggle('error-toast',error);$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,error?11000:6000);}
function downloadBlob(blob,fileName){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=fileName;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function csvCell(value){
 if(value==null)return '';
 let s=String(value);if(typeof value!=='number'&&/^[\s]*[=+@\-\t\r]/.test(s))s="'"+s;
 return '"'+s.replace(/"/g,'""')+'"';
}
