/* Minimal XLSX reader: ZIP central directory + XML. Reads cached cell values;
   recalculates Pending Amount from G/I/J and derives missing due dates. */
async function openZip(buffer){
 const bytes=new Uint8Array(buffer),dv=new DataView(buffer);let end=-1;
 if(bytes.length<22)throw new Error('The selected file is not a valid .xlsx workbook.');
 for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(dv.getUint32(i,true)===0x06054b50){end=i;break;}
 if(end<0)throw new Error('Cannot read this workbook. Use an unencrypted .xlsx file, not .xls or a password-protected file.');
 const entries=dv.getUint16(end+10,true),dirOffset=dv.getUint32(end+16,true);
 if(entries===65535||dirOffset===4294967295)throw new Error('ZIP64 workbooks are not supported by this lightweight reader.');
 if(entries>20000)throw new Error('This workbook has too many archive entries.');
 const decoder=new TextDecoder('utf-8');const map=new Map();let p=dirOffset,totalSize=0;
 for(let i=0;i<entries;i++){
  if(p+46>bytes.length||dv.getUint32(p,true)!==0x02014b50)throw new Error('Invalid workbook archive directory.');
  const flags=dv.getUint16(p+8,true),method=dv.getUint16(p+10,true),compressed=dv.getUint32(p+20,true),uncompressed=dv.getUint32(p+24,true),nameLen=dv.getUint16(p+28,true),extraLen=dv.getUint16(p+30,true),commentLen=dv.getUint16(p+32,true),offset=dv.getUint32(p+42,true);
  const name=decoder.decode(bytes.subarray(p+46,p+46+nameLen));totalSize+=uncompressed;
  if(totalSize>180000000)throw new Error('Workbook is too large after decompression (180 MB limit).');
  map.set(name,{flags,method,compressed,uncompressed,offset});p+=46+nameLen+extraLen+commentLen;
 }
 const cache=new Map();
 return {has:name=>map.has(name),async text(name){
  if(cache.has(name))return cache.get(name);const e=map.get(name);if(!e)return null;
  if(e.flags&1)throw new Error('Encrypted workbooks are not supported.');
  if(e.offset+30>bytes.length||dv.getUint32(e.offset,true)!==0x04034b50)throw new Error('Workbook ZIP entry is invalid.');
  const start=e.offset+30+dv.getUint16(e.offset+26,true)+dv.getUint16(e.offset+28,true);
  if(start+e.compressed>bytes.length)throw new Error('Workbook ZIP data is incomplete.');
  let data=bytes.subarray(start,start+e.compressed);
  if(e.method===8){
   let ds;try{ds=new DecompressionStream('deflate-raw');}catch(err){throw new Error('Excel import needs a modern Chrome or Edge browser with raw-deflate support. The embedded dashboard still works offline.');}
   data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(ds)).arrayBuffer());
  }else if(e.method!==0)throw new Error('Unsupported ZIP compression method in workbook.');
  if(data.length!==e.uncompressed)throw new Error('Workbook entry length does not match.');
  const text=decoder.decode(data);cache.set(name,text);return text;
 }};
}
function xml(text,label){if(!text)throw new Error('Missing '+label+' in workbook.');const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.getElementsByTagName('parsererror').length)throw new Error('Invalid XML in '+label+'.');return doc;}
const tags=(node,name)=>Array.from(node.getElementsByTagNameNS('*',name));
function colIndex(address){const m=address.match(/^[A-Z]+/i);if(!m)return 0;let n=0;for(const c of m[0].toUpperCase())n=n*26+c.charCodeAt(0)-64;return n-1;}
const decodeExcelText=s=>s.replace(/_x([0-9a-f]{4})_/ig,(_,hex)=>String.fromCharCode(parseInt(hex,16)));
function sheetGrid(text,shared){
 const doc=xml(text,'worksheet'),rows=[],formulas={};
 for(const node of tags(doc,'row')){
  const row=Number(node.getAttribute('r')),v=[];
  for(const c of tags(node,'c')){
   const address=c.getAttribute('r')||'',idx=colIndex(address),t=c.getAttribute('t');const vn=tags(c,'v')[0],f=tags(c,'f')[0];let value=vn?vn.textContent:null;
   if(f)formulas[address]='='+f.textContent;
   if(t==='s')value=value==null?null:shared[Number(value)]??null;
   else if(t==='inlineStr')value=decodeExcelText(tags(c,'t').map(x=>x.textContent).join(''));
   else if(t==='b')value=value==='1';
   else if(t!=='str'&&t!=='e'&&t!=='d'&&value!=null&&value!==''){const n=Number(value);if(Number.isFinite(n))value=n;}
   v[idx]=value;
  }
  rows.push({row,v});
 }
 return {rows,formulas,at(address){const rn=Number(address.match(/\d+$/)?.[0]);return rows.find(r=>r.row===rn)?.v[colIndex(address)]??null;}};
}
function resolveZipPath(base,path){
 if(path.startsWith('/'))return path.slice(1);const parts=(base+path).split('/'),out=[];
 for(const part of parts){if(part==='..')out.pop();else if(part&&part!=='.')out.push(part);}return out.join('/');
}
async function readXLSX(file){
 const z=await openZip(await file.arrayBuffer());
 const workbook=xml(await z.text('xl/workbook.xml'),'workbook.xml'),rels=xml(await z.text('xl/_rels/workbook.xml.rels'),'workbook relationships');
 const relationMap=new Map(tags(rels,'Relationship').filter(r=>r.getAttribute('TargetMode')!=='External').map(r=>[r.getAttribute('Id'),resolveZipPath('xl/',r.getAttribute('Target'))]));
 const sheets=tags(workbook,'sheet').map(s=>({name:s.getAttribute('name'),path:relationMap.get(s.getAttribute('r:id')||s.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id'))}));
 const dataSheet=sheets.find(s=>key(s.name)==='data');if(!dataSheet)throw new Error('No Data worksheet was found. Please upload the same receivables workbook layout.');
 let shared=[];
 if(z.has('xl/sharedStrings.xml')){const ss=xml(await z.text('xl/sharedStrings.xml'),'shared strings');shared=tags(ss,'si').map(si=>decodeExcelText(tags(si,'t').map(t=>t.textContent).join('')));}
 const data=sheetGrid(await z.text(dataSheet.path),shared);
 const customerHeaderKeys=new Set(['party','customer name','customer','party name']);
 const pendingHeaderKeys=new Set(['pending amount','pending amt','outstanding amount','balance amount']);
 const refHeaderKeys=new Set(['ref. no.','ref no','reference no','invoice no','invoice number','bill no','bill number']);
 const header=data.rows.slice(0,35).find(r=>r.v.some(v=>customerHeaderKeys.has(key(v)))&&r.v.some(v=>pendingHeaderKeys.has(key(v))));
 if(!header)throw new Error('Could not locate Party / Customer Name and Pending Amount headers in the Data sheet.');
 const normalizedHeaders=header.v.map(v=>{
  const k=key(v);
  if(customerHeaderKeys.has(k))return 'Party';
  if(pendingHeaderKeys.has(k))return 'Pending Amount';
  if(refHeaderKeys.has(k))return 'Ref. No.';
  return v;
 });
 let master=[], masterHeaders=[];const ms=sheets.find(s=>key(s.name)==='customer master'||key(s.name)==='master details'||key(s.name)==='customer details'||key(s.name)==='master');
 if(ms){const g=sheetGrid(await z.text(ms.path),shared);const mh=g.rows.find(r=>r.v.some(v=>customerHeaderKeys.has(key(v)))||r.v.some(v=>['customer contact','contact','mobile','city','email'].includes(key(v))));masterHeaders=mh?.v||[];master=g.rows.filter(r=>r.row>(mh?.row||2)&&r.v.some(v=>clean(v)));}
 let legacyTotal=null,legacyRangeEnd=null;const ds=sheets.find(s=>key(s.name)==='dashboard');
 if(ds){const g=sheetGrid(await z.text(ds.path),shared);legacyTotal=g.at('A6');const match=(g.formulas.A6||'').match(/\$?K\$?4:\$?K\$?(\d+)/i);if(match)legacyRangeEnd=Number(match[1]);}
 const date1904=['1','true'].includes(tags(workbook,'workbookPr')[0]?.getAttribute('date1904'));
 const ci=normalizedHeaders.findIndex(v=>key(v)==='party'),pi=normalizedHeaders.findIndex(v=>key(v)==='pending amount');
 return {schemaVersion:1,fileName:file.name,company:data.at('A1')||'BASIK INNOVATION LLP',snapshotDate:data.at('W1'),date1904,headers:normalizedHeaders,rows:data.rows.filter(r=>r.row>header.row&&clean(r.v[ci])),master,masterHeaders,sourceHeaderTotal:data.rows.find(r=>r.row===1)?.v[pi]??null,legacyTotal,legacyRangeEnd};
}
function mergeReceivablesSources(existingRaw,incomingRaw){
 if(!existingRaw||!Array.isArray(existingRaw.headers)||!Array.isArray(existingRaw.rows))throw new Error('Existing dashboard data is not valid.');
 if(!incomingRaw||!Array.isArray(incomingRaw.headers)||!Array.isArray(incomingRaw.rows))throw new Error('Uploaded workbook data is not valid.');

 // Build one union header list so old data is preserved even if the new file adds columns.
 // Common aliases are canonicalised so weekly uploads using "Customer Name" still merge with old "Party" rows.
 const canonicalHeaderKey=h=>{
  const k=key(h);
  if(['party','customer name','customer','party name'].includes(k))return 'party';
  if(['pending amount','pending amt','outstanding amount','balance amount'].includes(k))return 'pending amount';
  if(['ref. no.','ref no','reference no','invoice no','invoice number','bill no','bill number'].includes(k))return 'ref. no.';
  return k;
 };
 const canonicalHeaderLabel=h=>{
  const k=canonicalHeaderKey(h);
  if(k==='party')return 'Party';
  if(k==='pending amount')return 'Pending Amount';
  if(k==='ref. no.')return 'Ref. No.';
  return clean(h);
 };
 const headers=[];
 const headerKeys=new Set();
 for(const h of [...existingRaw.headers,...incomingRaw.headers]){
  const label=canonicalHeaderLabel(h);
  const k=canonicalHeaderKey(h);
  if(!label||headerKeys.has(k))continue;
  headerKeys.add(k);headers.push(label);
 }
 const unionIndex=new Map(headers.map((h,i)=>[canonicalHeaderKey(h),i]));
 const remap=(raw,item)=>{
  const sourceIndex=new Map(raw.headers.map((h,i)=>[canonicalHeaderKey(h),i]));
  const out=new Array(headers.length).fill(null);
  for(const [hk,si] of sourceIndex){const ui=unionIndex.get(hk);if(ui!=null)out[ui]=(item.v||[])[si]??null;}
  return {row:Number(item.row)||0,v:out};
 };
 const value=(row,name)=>{const i=unionIndex.get(canonicalHeaderKey(name));return i==null?null:row.v[i];};
 const usableRef=v=>{const s=clean(v);return s&&!/^(?:n\/?a|#n\/?a|na|none|null|no ref(?:erence)?|\(no reference\))$/i.test(s);};
 const rowKey=row=>{
  const party=key(value(row,'Party'));
  const ref=clean(value(row,'Ref. No.'));
  if(party&&usableRef(ref))return 'invoice|'+party+'|'+key(ref);

  // Fallback for rows without an invoice reference. These fields are comparatively stable
  // across weekly re-uploads while mutable receipt/pending values are intentionally excluded.
  const bill=clean(value(row,'Bill Date'));
  const due=clean(value(row,'Due Date'));
  const opening=clean(value(row,'Opening Amount'));
  const oldPending=clean(value(row,'OLD Pending Amount'));
  const terms=clean(value(row,'Terms'));
  if(party&&(bill||due||opening||oldPending))return 'fallback|'+party+'|'+key(bill)+'|'+key(due)+'|'+key(opening)+'|'+key(oldPending)+'|'+key(terms);
  return 'row|'+party+'|'+String(row.row);
 };

 const merged=new Map();
 let duplicateExisting=0,duplicateIncoming=0,replacedByUpload=0,added=0;
 for(const item of existingRaw.rows){
  const row=remap(existingRaw,item),k=rowKey(row);
  if(merged.has(k))duplicateExisting++;
  merged.set(k,row);
 }
 const oldKeys=new Set(merged.keys());
 const seenIncoming=new Set();
 for(const item of incomingRaw.rows){
  const row=remap(incomingRaw,item),k=rowKey(row);
  const repeatedInUpload=seenIncoming.has(k);
  if(repeatedInUpload)duplicateIncoming++;
  else if(oldKeys.has(k))replacedByUpload++;
  else added++;
  seenIncoming.add(k);
  // The latest upload wins for an existing invoice, so receipts/pending/remarks get refreshed.
  merged.set(k,row);
 }

 // Renumber the merged snapshot to guarantee unique internal row IDs after incremental uploads.
 const rows=[...merged.values()].map((r,i)=>({row:i+4,v:r.v}));

 const mergeMaster=(a,b)=>{
  const m=new Map();
  for(const item of [...(a||[]),...(b||[])]){
   const v=item.v||item;
   const party=key(v&&v[1]);
   if(party)m.set(party,item);
  }
  return [...m.values()];
 };

 const mergedRaw={
  ...existingRaw,
  ...incomingRaw,
  schemaVersion:Math.max(Number(existingRaw.schemaVersion)||1,Number(incomingRaw.schemaVersion)||1),
  fileName:(incomingRaw.fileName||'Imported workbook')+' (merged)',
  company:incomingRaw.company||existingRaw.company,
  snapshotDate:incomingRaw.snapshotDate||existingRaw.snapshotDate,
  date1904:incomingRaw.date1904 ?? existingRaw.date1904,
  headers,
  rows,
  master:mergeMaster(existingRaw.master,incomingRaw.master),
  masterHeaders:incomingRaw.masterHeaders||existingRaw.masterHeaders||[],
  // These totals belong to the individual source workbook and may not reconcile after an incremental merge.
  sourceHeaderTotal:null,
  legacyTotal:null,
  legacyRangeEnd:null
 };
 return {raw:mergedRaw,stats:{existing:existingRaw.rows.length,incoming:incomingRaw.rows.length,added,replaced:replacedByUpload,duplicatesRemoved:duplicateExisting+duplicateIncoming,total:rows.length}};
}
async function importFile(file){
 if(!file)return;
 if(file.size>35000000){toast('Please use a workbook smaller than 35 MB.',true);return;}
 $('busy').hidden=false;
 try{
  await new Promise(resolve=>setTimeout(resolve,40));
  const incoming=/\.xlsx$/i.test(file.name)?await readXLSX(file):/\.json$/i.test(file.name)?JSON.parse(await file.text()):null;
  if(!incoming)throw new Error('Select an .xlsx workbook or a compatible dashboard .json snapshot.');

  // MERGE instead of replace: old unique rows stay, new rows are added, matching invoices are refreshed.
  const merged=mergeReceivablesSources(source,incoming);
  initialize(merged.raw,false);
  if(window.serverSaveImportedData) await window.serverSaveImportedData(merged.raw);
  toast('Import complete: '+intFormat.format(merged.stats.added)+' new rows added, '+intFormat.format(merged.stats.replaced)+' existing rows refreshed, '+intFormat.format(merged.stats.duplicatesRemoved)+' duplicate rows removed. Total '+intFormat.format(merged.stats.total)+' rows saved.');
 }catch(err){console.error(err);toast('Import failed: '+err.message+' Existing data has not been replaced.',true);}
 finally{$('busy').hidden=true;$('fileInput').value='';}
}
