if($('grnExportBtn'))$('grnExportBtn').addEventListener('click',()=>exportProcurementCsv('grn'));
for(const field of ['coordinator','customerType','customer','bdm','ageing','status'])$(field).addEventListener('change',()=>{state[field]=$(field).value;state.page=1;render();});
$('dateRange').addEventListener('change',()=>{applyDateRange($('dateRange').value);state.page=1;render();});
$('dateModeTop').addEventListener('change',()=>{state.dateMode=$('dateModeTop').value||'due';state.page=1;render();});
$('dateFromTop').addEventListener('change',applyCustomDates);
$('dateToTop').addEventListener('change',applyCustomDates);
let searchTimer;
$('search').addEventListener('focus',showCustomerSuggestions);
$('search').addEventListener('input',()=>{showCustomerSuggestions();clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.query=$('search').value;state.page=1;render();},120);});
$('search').addEventListener('keydown',event=>{
 if(event.key==='ArrowDown'){event.preventDefault();if($('customerSuggestions').hidden)showCustomerSuggestions();else moveCustomerSuggestion(1);}
 else if(event.key==='ArrowUp'){event.preventDefault();moveCustomerSuggestion(-1);}
 else if(event.key==='Enter'&&!$('customerSuggestions').hidden&&customerSuggestionIndex>=0){event.preventDefault();const b=$('customerSuggestions').querySelectorAll('.search-suggestion')[customerSuggestionIndex];if(b)chooseCustomerSuggestion(b.dataset.customerSuggestion);}
 else if(event.key==='Escape')hideCustomerSuggestions();
});
document.addEventListener('click',event=>{if(!event.target.closest('.search-field'))hideCustomerSuggestions();});
document.addEventListener('input',event=>{const bill=event.target.closest('[data-bill-followup]');if(bill){bill.dataset.dirty='1';bill.classList.add('unsaved');return;}const el=event.target.closest('[data-party-remark]');if(!el)return;markPartyRemarkUnsaved(el);});
$('asof').addEventListener('change',()=>{const d=isoDate($('asof').value);if(!d||d<'2000-01-01'||d>'2100-12-31'){toast('Choose a valid ageing date from 2000 to 2100.',true);$('asof').value=state.asof;return;}state.asof=d;state.page=1;render();});
$('unit').addEventListener('change',()=>{state.unit=$('unit').value;render();});
$('moreFilters').onclick=()=>{$('extraFilters').hidden=!$('extraFilters').hidden;$('moreFilters').setAttribute('aria-expanded',String(!$('extraFilters').hidden));renderChips();};
$('resetBtn').onclick=resetFilters;$('helpBtn').onclick=()=>$('helpDialog').showModal();$('helpTopBtn').onclick=()=>$('helpDialog').showModal();
if($('masterSearch'))$('masterSearch').addEventListener('input',()=>{state.masterQuery=$('masterSearch').value||'';state.page=1;if(state.view==='master')render();});
if($('masterSaveBtn'))$('masterSaveBtn').onclick=saveMasterData;
if($('masterAddRowBtn'))$('masterAddRowBtn').onclick=addMasterRow;
if($('masterDuplicateRowBtn'))$('masterDuplicateRowBtn').onclick=duplicateMasterRows;
if($('masterDeleteRowBtn'))$('masterDeleteRowBtn').onclick=deleteMasterRows;
if($('masterAddColumnBtn'))$('masterAddColumnBtn').onclick=addMasterColumn;
if($('masterRenameColumnBtn'))$('masterRenameColumnBtn').onclick=renameMasterColumn;
if($('masterDeleteColumnBtn'))$('masterDeleteColumnBtn').onclick=deleteMasterColumn;
if($('masterColumnSelect'))$('masterColumnSelect').addEventListener('change',()=>{masterSelectedColumn=Number($('masterColumnSelect').value)||0;if(state.view==='master')renderMasterData();});
if($('masterTable')){
 $('masterTable').addEventListener('click',event=>{
  const head=event.target.closest('[data-master-col-head]');
  if(head){masterSelectedColumn=Number(head.dataset.masterColHead)||0;refreshMasterColumnSelect();renderMasterData();return;}
  if(event.target&&event.target.id==='masterSelectAll'){
   document.querySelectorAll('.master-row-check:not(#masterSelectAll)').forEach(cb=>{cb.checked=event.target.checked;});
  }
 });
 $('masterTable').addEventListener('input',event=>{
  const cell=event.target.closest('[data-master-row][data-master-col]');if(!cell)return;
  const r=Number(cell.dataset.masterRow),c=Number(cell.dataset.masterCol);
  if(!source.rows[r])return;
  normalizeSourceForMaster();
  source.rows[r].v[c]=cell.textContent.trim();
  setMasterDirty(true,'Unsaved: cell edited');
 });
 $('masterTable').addEventListener('paste',event=>{
  const cell=event.target.closest('[data-master-row][data-master-col]');if(!cell)return;
  const text=(event.clipboardData||window.clipboardData)?.getData('text');
  if(!text||(!text.includes('\t')&&!text.includes('\n')))return;
  event.preventDefault();normalizeSourceForMaster();
  const startRow=Number(cell.dataset.masterRow),startCol=Number(cell.dataset.masterCol);
  const lines=text.replace(/\r/g,'').split('\n').filter((line,i,a)=>line!==''||i<a.length-1);
  for(let r=0;r<lines.length;r++){
   const values=lines[r].split('\t');
   const targetRow=startRow+r;
   while(targetRow>=source.rows.length)source.rows.push({row:nextMasterRowNumber(),v:Array(source.headers.length).fill('')});
   for(let c=0;c<values.length;c++){
    const targetCol=startCol+c;
    while(targetCol>=source.headers.length){source.headers.push('Column '+(source.headers.length+1));for(const row of source.rows)row.v.push('');}
    source.rows[targetRow].v[targetCol]=values[c];
   }
  }
  setMasterDirty(true,'Unsaved: pasted data');
  renderMasterData();
 });
}
$('exportBtn').onclick=exportCSV;const excelBtn=$('exportExcelBtn');if(excelBtn)excelBtn.onclick=exportExcel;const pdfBtn=$('pdfBtn');if(pdfBtn)pdfBtn.onclick=exportPDF;const printHeaderBtn=$('printHeaderBtn');if(printHeaderBtn)printHeaderBtn.onclick=()=>window.print();const templateBtn=$('templateBtn');if(templateBtn)templateBtn.onclick=downloadTemplate;const saveVisibleBtn=$('saveVisibleRemarksBtn');if(saveVisibleBtn)saveVisibleBtn.onclick=saveVisiblePartyRemarks;const exportRemarksBtn=$('exportRemarksBtn');if(exportRemarksBtn)exportRemarksBtn.onclick=()=>{const oldView=state.view;state.view='remarks';exportCSV();state.view=oldView;};$('exportAgeSummary').onclick=exportAgeSummary;$('saveHtmlBtn').onclick=saveHTML;
$('importBtn').onclick=()=>$('fileInput').click();$('fileInput').onchange=()=>importFile($('fileInput').files[0]);
if($('crmFilter'))$('crmFilter').addEventListener('change',()=>{state.crm=$('crmFilter').value;state.page=1;render();});
if($('crmClearBtn'))$('crmClearBtn').onclick=()=>{state.crm='';if($('crmFilter'))$('crmFilter').value='';state.page=1;render();};
if($('exportCrmBtn'))$('exportCrmBtn').onclick=exportCrmCSV;
$('printBtn').onclick=()=>{if(['customers','bills','ageing','overdue','weekly','remarks'].includes(state.view))toast('Print uses the current table page. Use Export CSV for all filtered rows.');window.print();};
const weeklyExportBtn=$('exportWeeklyBtn');if(weeklyExportBtn)weeklyExportBtn.onclick=exportWeekly;
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
try{initialize(source);}catch(err){console.error(err);$('pageSubtitle').textContent='The embedded data could not be loaded: '+err.message;toast(err.message,true);}
</script>
</body></html>
